  1→/**
  2→ * Build AI SDK tools from an agent's collections and individual tools
  3→ */
  4→
  5→import type { Agent, AgentCollection, AgentTool, Collection, Package, Tool } from '@tpmjs/db';
  6→import { prisma } from '@tpmjs/db';
  7→
  8→import { jsonSchema } from 'ai';
  9→
 10→import { createToolDefinition } from '../ai-agent/tool-executor-agent';
 11→import { executeWithSandbox, parseExecutorConfig, resolveExecutorConfig } from '../executors';
 12→
 13→// Agent type includes executor config fields from Prisma schema
 14→type AgentWithRelations = Agent & {
 15→  collections: (AgentCollection & {
 16→    collection: Collection & {
 17→      tools: Array<{
 18→        tool: Tool & { package: Package };
 19→      }>;
 20→    };
 21→  })[];
 22→  tools: (AgentTool & {
 23→    tool: Tool & { package: Package };
 24→  })[];
 25→};
 26→
 27→/**
 28→ * Fetch a full agent with all tool relations
 29→ * Includes executor config for cascade resolution
 30→ */
 31→export async function fetchAgentWithTools(agentId: string): Promise<AgentWithRelations | null> {
 32→  return prisma.agent.findUnique({
 33→    where: { id: agentId },
 34→    include: {
 35→      collections: {
 36→        include: {
 37→          collection: {
 38→            include: {
 39→              tools: {
 40→                include: {
 41→                  tool: {
 42→                    include: { package: true },
 43→                  },
 44→                },
 45→                orderBy: { position: 'asc' },
 46→              },
 47→            },
 48→          },
 49→        },
 50→        orderBy: { position: 'asc' },
 51→      },
 52→      tools: {
 53→        include: {
 54→          tool: {
 55→            include: { package: true },
 56→          },
 57→        },
 58→        orderBy: { position: 'asc' },
 59→      },
 60→    },
 61→  });
 62→}
 63→
 64→/**
 65→ * Fetch an agent by UID with all tool relations
 66→ * Includes executor config for cascade resolution
 67→ */
 68→export async function fetchAgentByUidWithTools(uid: string): Promise<AgentWithRelations | null> {
 69→  return prisma.agent.findUnique({
 70→    where: { uid },
 71→    include: {
 72→      collections: {
 73→        include: {
 74→          collection: {
 75→            include: {
 76→              tools: {
 77→                include: {
 78→                  tool: {
 79→                    include: { package: true },
 80→                  },
 81→                },
 82→                orderBy: { position: 'asc' },
 83→              },
 84→            },
 85→          },
 86→        },
 87→        orderBy: { position: 'asc' },
 88→      },
 89→      tools: {
 90→        include: {
 91→          tool: {
 92→            include: { package: true },
 93→          },
 94→        },
 95→        orderBy: { position: 'asc' },
 96→      },
 97→    },
 98→  });
 99→}
100→
101→/**
102→ * Fetch an agent by ID or UID with all tool relations
103→ * Accepts either the cuid or the user-friendly uid
104→ * Includes executor config for cascade resolution
105→ */
106→export async function fetchAgentByIdOrUidWithTools(
107→  idOrUid: string
108→): Promise<AgentWithRelations | null> {
109→  return prisma.agent.findFirst({
110→    where: {
111→      OR: [{ id: idOrUid }, { uid: idOrUid }],
112→    },
113→    include: {
114→      collections: {
115→        include: {
116→          collection: {
117→            include: {
118→              tools: {
119→                include: {
120→                  tool: {
121→                    include: { package: true },
122→                  },
123→                },
124→                orderBy: { position: 'asc' },
125→              },
126→            },
127→          },
128→        },
129→        orderBy: { position: 'asc' },
130→      },
131→      tools: {
132→        include: {
133→          tool: {
134→            include: { package: true },
135→          },
136→        },
137→        orderBy: { position: 'asc' },
138→      },
139→    },
140→  });
141→}
142→
143→/**
144→ * Fetch an agent by username and uid with all tool relations
145→ * Uses the username/uid pretty URL format
146→ * Includes executor config for cascade resolution
147→ */
148→export async function fetchAgentByUsernameAndUidWithTools(
149→  username: string,
150→  uid: string
151→): Promise<AgentWithRelations | null> {
152→  return prisma.agent.findFirst({
153→    where: {
154→      uid,
155→      user: { username },
156→    },
157→    include: {
158→      collections: {
159→        include: {
160→          collection: {
161→            include: {
162→              tools: {
163→                include: {
164→                  tool: {
165→                    include: { package: true },
166→                  },
167→                },
168→                orderBy: { position: 'asc' },
169→              },
170→            },
171→          },
172→        },
173→        orderBy: { position: 'asc' },
174→      },
175→      tools: {
176→        include: {
177→          tool: {
178→            include: { package: true },
179→          },
180→        },
181→        orderBy: { position: 'asc' },
182→      },
183→    },
184→  });
185→}
186→
187→/**
188→ * Sanitize npm package name to valid tool name
189→ * OpenAI limits tool names to 64 characters
190→ */
191→function sanitizeToolName(name: string): string {
192→  const sanitized = name.replace(/[@/]/g, '-').replace(/^-+/, '');
193→  // Truncate to 64 chars (OpenAI limit)
194→  return sanitized.slice(0, 64);
195→}
196→
197→/**
198→ * Parse environment variables from JSON field
199→ * Returns empty object if null/undefined or invalid
200→ */
201→function parseEnvVars(envVars: unknown): Record<string, string> {
202→  if (!envVars || typeof envVars !== 'object') {
203→    return {};
204→  }
205→  // Validate all values are strings
206→  const result: Record<string, string> = {};
207→  for (const [key, value] of Object.entries(envVars)) {
208→    if (typeof value === 'string') {
209→      result[key] = value;
210→    }
211→  }
212→  return result;
213→}
214→
215→/**
216→ * Merge environment variables with agent envVars taking precedence
217→ * Collection envVars are used as base, agent envVars override
218→ */
219→function mergeEnvVars(
220→  collectionEnvVars: Record<string, string>,
221→  agentEnvVars: Record<string, string>
222→): Record<string, string> {
223→  return {
224→    ...collectionEnvVars,
225→    ...agentEnvVars, // Agent overrides collection
226→  };
227→}
228→
229→/**
230→ * Inject sandbox tools (shellExec, readFile, writeFile, listFiles)
231→ * These are hard-coded tool definitions that route directly to the sandbox server.
232→ */
233→function injectSandboxTools(
234→  sandboxUrl: string,
235→  sandboxApiKey: string | undefined,
236→  sessionId: string,
237→  env?: Record<string, string>
238→): Record<string, ReturnType<typeof createToolDefinition>> {
239→  const makeSandboxTool = (
240→    name: string,
241→    description: string,
242→    schema: Record<string, unknown>,
243→    paramMapper: (params: Record<string, unknown>) => Record<string, unknown>
244→  ) => ({
245→    description,
246→    inputSchema: jsonSchema(schema as Parameters<typeof jsonSchema>[0]),
247→    execute: async (args: Record<string, unknown>) => {
248→      const result = await executeWithSandbox(
249→        sandboxUrl,
250→        sandboxApiKey,
251→        {
252→          packageName: '@tpmjs/sandbox-shell',
253→          name,
254→          params: paramMapper(args),
255→          env,
256→        },
257→        sessionId
258→      );
259→      return result.success ? result.output : { error: result.error };
260→    },
261→  });
262→
263→  return {
264→    shellExec: makeSandboxTool(
265→      'shellExec',
266→      'Execute a shell command in the sandbox workspace. Commands run in a persistent bash session with the workspace as the working directory.',
267→      {
268→        type: 'object',
269→        properties: {
270→          command: { type: 'string', description: 'Shell command to execute' },
271→          timeout: {
272→            type: 'number',
273→            description: 'Timeout in milliseconds (default: 30000, max: 300000)',
274→          },
275→        },
276→        required: ['command'],
277→      },
278→      (p) => p
279→    ),
280→    readFile: makeSandboxTool(
281→      'readFile',
282→      'Read the contents of a file in the sandbox workspace.',
283→      {
284→        type: 'object',
285→        properties: {
286→          path: { type: 'string', description: 'File path relative to workspace root' },
287→        },
288→        required: ['path'],
289→      },
290→      (p) => p
291→    ),
292→    writeFile: makeSandboxTool(
293→      'writeFile',
294→      'Write content to a file in the sandbox workspace. Creates parent directories if needed.',
295→      {
296→        type: 'object',
297→        properties: {
298→          path: { type: 'string', description: 'File path relative to workspace root' },
299→          content: { type: 'string', description: 'File content to write' },
300→          createDirs: {
301→            type: 'boolean',
302→            description: 'Create parent directories if they do not exist (default: true)',
303→          },
304→        },
305→        required: ['path', 'content'],
306→      },
307→      (p) => p
308→    ),
309→    listFiles: makeSandboxTool(
310→      'listFiles',
311→      'List files and directories in the sandbox workspace.',
312→      {
313→        type: 'object',
314→        properties: {
315→          path: {
316→            type: 'string',
317→            description: 'Directory path relative to workspace root (default: ".")',
318→          },
319→          recursive: { type: 'boolean', description: 'List files recursively (default: false)' },
320→          maxDepth: {
321→            type: 'number',
322→            description: 'Maximum directory depth for recursive listing (default: 3)',
323→          },
324→        },
325→      },
326→      (p) => p
327→    ),
328→  };
329→}
330→
331→/**
332→ * Build all tools from an agent's collections and individual tools
333→ * Returns a map of tool name -> AI SDK tool definition
334→ *
335→ * Executor config cascade: Agent → Collection → System Default
336→ * - If agent has an executor config, it's used for all tools
337→ * - If agent has no config but collection has one, collection's config is used for tools from that collection
338→ * - If neither has config, system default is used
339→ *
340→ * Environment variables cascade: Agent → Collection (merged, agent overrides)
341→ * - Collection env vars are used as base
342→ * - Agent env vars override collection env vars for same keys
343→ * - Both are merged together for unique keys
344→ *
345→ * @param agent - The agent with tool relations
346→ * @param callerEnvVars - Optional env vars provided by the caller (for non-owners accessing public agents).
347→ *                        When provided, these are used INSTEAD of the agent's stored env vars.
348→ * @param sessionId - Optional session ID for sandbox executors
349→ * @param sandboxUrl - Optional sandbox URL for injecting sandbox tools
350→ * @param sandboxApiKey - Optional sandbox API key
351→ */
352→export function buildAgentTools(
353→  agent: AgentWithRelations,
354→  callerEnvVars?: Record<string, string>,
355→  sessionId?: string,
356→  sandboxUrl?: string,
357→  sandboxApiKey?: string
358→): Record<string, ReturnType<typeof createToolDefinition>> {
359→  const tools: Record<string, ReturnType<typeof createToolDefinition>> = {};
360→  const seenTools = new Set<string>();
361→
362→  // When callerEnvVars is provided (non-owner using public agent), use those exclusively.
363→  // Otherwise, use the agent's stored env vars.
364→  const useCallerEnvVars = callerEnvVars !== undefined;
365→  const agentEnvVars = useCallerEnvVars ? callerEnvVars : parseEnvVars(agent.envVars);
366→
367→  // Inject sandbox tools first if sandbox is enabled and session is active
368→  if (sandboxUrl && sessionId) {
369→    const sandboxTools = injectSandboxTools(sandboxUrl, sandboxApiKey, sessionId, agentEnvVars);
370→    for (const [name, toolDef] of Object.entries(sandboxTools)) {
371→      tools[name] = toolDef;
372→      // Mark sandbox tool package keys as seen to prevent duplicates
373→      // if the sandbox-shell collection is also attached
374→      seenTools.add(`@tpmjs/sandbox-shell::${name}`);
375→    }
376→  }
377→
378→  // Parse agent-level executor config
379→  const agentExecutorConfig = parseExecutorConfig(agent.executorType, agent.executorConfig);
380→
381→  // Add tools from collections first
382→  for (const agentCollection of agent.collections) {
383→    const collection = agentCollection.collection;
384→
385→    // Parse collection-level executor config
386→    const collectionExecutorConfig = parseExecutorConfig(
387→      collection.executorType,
388→      collection.executorConfig
389→    );
390→
391→    // Resolve executor config: Agent → Collection → Default
392→    const resolvedConfig = resolveExecutorConfig(agentExecutorConfig, collectionExecutorConfig);
393→
394→    // Parse collection-level env vars and merge with agent env vars
395→    // When callerEnvVars is provided, skip collection env vars entirely
396→    const collectionEnvVars = useCallerEnvVars ? {} : parseEnvVars(collection.envVars);
397→    const mergedEnvVars = mergeEnvVars(collectionEnvVars, agentEnvVars);
398→
399→    for (const collectionTool of collection.tools) {
400→      const tool = collectionTool.tool;
401→      const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
402→
403→      // Avoid duplicates
404→      if (seenTools.has(toolKey)) continue;
405→      seenTools.add(toolKey);
406→
407→      const toolName = sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`);
408→      tools[toolName] = createToolDefinition(tool, resolvedConfig, mergedEnvVars);
409→    }
410→  }
411→
412→  // Add individual tools (may override collection tools)
413→  // Individual tools use agent config or system default (no collection context)
414→  // Individual tools only use agent env vars (no collection context)
415→  const individualToolConfig = agentExecutorConfig ?? { type: 'default' as const };
416→
417→  for (const agentTool of agent.tools) {
418→    const tool = agentTool.tool;
419→    const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
420→
421→    // Skip if already added from collections
422→    if (seenTools.has(toolKey)) continue;
423→    seenTools.add(toolKey);
424→
425→    const toolName = sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`);
426→    tools[toolName] = createToolDefinition(tool, individualToolConfig, agentEnvVars);
427→  }
428→
429→  return tools;
430→}
431→
432→/**
433→ * Get list of tool names for an agent (for display)
434→ */
435→export function getAgentToolNames(agent: AgentWithRelations): string[] {
436→  const names: string[] = [];
437→  const seenTools = new Set<string>();
438→
439→  for (const agentCollection of agent.collections) {
440→    for (const collectionTool of agentCollection.collection.tools) {
441→      const tool = collectionTool.tool;
