   1→/**
   2→ * Agent Conversation Endpoint (ID-based version)
   3→ *
   4→ * POST: Send a message and stream the AI response
   5→ * GET: Retrieve conversation history
   6→ * DELETE: Delete a conversation
   7→ *
   8→ * This endpoint uses agent id directly for dashboard usage.
   9→ *
  10→ * Authentication: Supports both session auth and TPMJS API key auth.
  11→ * Requires 'agent:chat' scope for API key access.
  12→ */
  13→
  14→import { randomUUID } from 'node:crypto';
  15→import { Prisma, prisma } from '@tpmjs/db';
  16→import type { AIProvider } from '@tpmjs/types/agent';
  17→import { SendMessageSchema } from '@tpmjs/types/agent';
  18→import type { LanguageModel, ModelMessage } from 'ai';
  19→import { type NextRequest, NextResponse } from 'next/server';
  20→import { decryptApiKey } from '@/lib/crypto/api-keys';
  21→import { logActivity } from '~/lib/activity';
  22→import { authenticateRequest, hasScope } from '~/lib/api-keys/middleware';
  23→import { trackUsage } from '~/lib/api-keys/usage';
  24→import { checkRateLimit, type RateLimitConfig } from '~/lib/rate-limit';
  25→import { inferErrorCategory } from '~/lib/tracking/error-categories';
  26→import { trackExecution } from '~/lib/tracking/executions';
  27→
  28→/**
  29→ * Rate limit for chat messages: 30 requests per minute
  30→ * This is stricter than default because chat involves expensive LLM calls
  31→ */
  32→const CHAT_RATE_LIMIT: RateLimitConfig = {
  33→  limit: 30,
  34→  windowSeconds: 60,
  35→};
  36→
  37→export const runtime = 'nodejs';
  38→export const dynamic = 'force-dynamic';
  39→export const maxDuration = 300; // 5 minutes for long agentic runs
  40→
  41→type RouteContext = {
  42→  params: Promise<{ id: string; conversationId: string }>;
  43→};
  44→
  45→/**
  46→ * Get AI provider SDK based on provider type
  47→ */
  48→async function getProviderModel(
  49→  provider: AIProvider,
  50→  modelId: string,
  51→  apiKey: string
  52→): Promise<LanguageModel> {
  53→  switch (provider) {
  54→    case 'OPENAI': {
  55→      const { createOpenAI } = await import('@ai-sdk/openai');
  56→      return createOpenAI({ apiKey })(modelId);
  57→    }
  58→    case 'ANTHROPIC': {
  59→      const { createAnthropic } = await import('@ai-sdk/anthropic');
  60→      return createAnthropic({ apiKey })(modelId);
  61→    }
  62→    case 'GOOGLE': {
  63→      const { createGoogleGenerativeAI } = await import('@ai-sdk/google');
  64→      return createGoogleGenerativeAI({ apiKey })(modelId);
  65→    }
  66→    case 'GROQ': {
  67→      const { createGroq } = await import('@ai-sdk/groq');
  68→      return createGroq({ apiKey })(modelId);
  69→    }
  70→    case 'MISTRAL': {
  71→      const { createMistral } = await import('@ai-sdk/mistral');
  72→      return createMistral({ apiKey })(modelId);
  73→    }
  74→    default:
  75→      throw new Error(`Unsupported provider: ${provider}`);
  76→  }
  77→}
  78→
  79→/**
  80→ * POST /api/agents/[id]/conversation/[conversationId]
  81→ * Send a message and stream the AI response via SSE
  82→ */
  83→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic required
  84→export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
  85→  const startTime = Date.now();
  86→
  87→  // Authenticate request (supports both session and API key)
  88→  const authResult = await authenticateRequest();
  89→
  90→  if (!authResult.authenticated) {
  91→    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  92→  }
  93→
  94→  // Check scope for API key auth
  95→  if (authResult.authenticated && !authResult.isSessionAuth) {
  96→    if (!hasScope(authResult, 'agent:chat')) {
  97→      return NextResponse.json(
  98→        { error: 'API key does not have agent:chat scope' },
  99→        { status: 403 }
 100→      );
 101→    }
 102→  }
 103→
 104→  // Check rate limit (after auth so we can track by user if needed)
 105→  const rateLimitResponse = checkRateLimit(request, CHAT_RATE_LIMIT);
 106→  if (rateLimitResponse) {
 107→    return rateLimitResponse;
 108→  }
 109→
 110→  const { id: agentId, conversationId } = await context.params;
 111→
 112→  try {
 113→    const body = await request.json();
 114→    const parsed = SendMessageSchema.safeParse(body);
 115→    if (!parsed.success) {
 116→      return NextResponse.json(
 117→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
 118→        { status: 400 }
 119→      );
 120→    }
 121→
 122→    // Fetch agent with all tool relations using agent ID
 123→    const { fetchAgentWithTools, buildAgentTools } = await import('@/lib/agents/build-tools');
 124→    const { getRequiredEnvVarsForAgent, getMissingEnvVars } = await import(
 125→      '@/lib/agents/env-helpers'
 126→    );
 127→    const agent = await fetchAgentWithTools(agentId);
 128→
 129→    if (!agent) {
 130→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
 131→    }
 132→
 133→    // Check ownership
 134→    const isOwner = authResult.userId === agent.userId;
 135→
 136→    // Non-owners can only access PUBLIC agents
 137→    if (!isOwner && !agent.isPublic) {
 138→      // Don't reveal that the agent exists - return 404
 139→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
 140→    }
 141→
 142→    // Map provider to expected key name format
 143→    const providerKeyNames: Record<string, string> = {
 144→      OPENAI: 'OPENAI_API_KEY',
 145→      ANTHROPIC: 'ANTHROPIC_API_KEY',
 146→      GOOGLE: 'GOOGLE_API_KEY',
 147→      GROQ: 'GROQ_API_KEY',
 148→      MISTRAL: 'MISTRAL_API_KEY',
 149→    };
 150→    const keyName = providerKeyNames[agent.provider];
 151→
 152→    if (!keyName) {
 153→      return NextResponse.json(
 154→        { success: false, error: `Unsupported provider: ${agent.provider}` },
 155→        { status: 400 }
 156→      );
 157→    }
 158→
 159→    let apiKey: string;
 160→    let callerEnvVars: Record<string, string> | undefined;
 161→
 162→    if (isOwner) {
 163→      // Owner: use stored encrypted keys
 164→      const userApiKey = await prisma.userApiKey.findUnique({
 165→        where: {
 166→          userId_keyName: {
 167→            userId: agent.userId,
 168→            keyName,
 169→          },
 170→        },
 171→      });
 172→
 173→      if (!userApiKey) {
 174→        return NextResponse.json(
 175→          {
 176→            success: false,
 177→            error: `No API key configured for ${agent.provider}. Please add your API key in settings.`,
 178→          },
 179→          { status: 400 }
 180→        );
 181→      }
 182→
 183→      // Decrypt the API key
 184→      apiKey = decryptApiKey(userApiKey.encryptedKey, userApiKey.keyIv);
 185→      // callerEnvVars stays undefined - buildAgentTools will use agent's stored env vars
 186→    } else {
 187→      // Non-owner accessing public agent: must provide their own credentials
 188→      if (!parsed.data.providerApiKey) {
 189→        return NextResponse.json(
 190→          {
 191→            success: false,
 192→            error: 'Public agent access requires your own API key',
 193→            details: {
 194→              code: 'MISSING_PROVIDER_KEY',
 195→              requiredProvider: agent.provider,
 196→              hint: `Provide your ${agent.provider} API key in the 'providerApiKey' field`,
 197→            },
 198→          },
 199→          { status: 400 }
 200→        );
 201→      }
 202→
 203→      apiKey = parsed.data.providerApiKey;
 204→      callerEnvVars = parsed.data.env || {};
 205→
 206→      // Check for required environment variables
 207→      const requiredEnvVars = getRequiredEnvVarsForAgent(agent);
 208→      const missingEnvVars = getMissingEnvVars(requiredEnvVars, callerEnvVars);
 209→
 210→      if (missingEnvVars.length > 0) {
 211→        return NextResponse.json(
 212→          {
 213→            success: false,
 214→            error: 'Missing required environment variables',
 215→            details: {
 216→              code: 'MISSING_ENV_VARS',
 217→              missingVars: missingEnvVars.map((e) => ({
 218→                name: e.name,
 219→                description: e.description,
 220→              })),
 221→              hint: "Provide these variables in the 'env' field of your request",
 222→            },
 223→          },
 224→          { status: 400 }
 225→        );
 226→      }
 227→    }
 228→
 229→    // Get or create conversation
 230→    let conversation = await prisma.conversation.findUnique({
 231→      where: {
 232→        agentId_slug: {
 233→          agentId: agent.id,
 234→          slug: conversationId,
 235→        },
 236→      },
 237→    });
 238→
 239→    if (!conversation) {
 240→      conversation = await prisma.conversation.create({
 241→        data: {
 242→          agentId: agent.id,
 243→          slug: conversationId,
 244→          title: parsed.data.message.slice(0, 100),
 245→        },
 246→      });
 247→
 248→      // Log activity for new conversation (fire-and-forget)
 249→      if (agent.userId) {
 250→        logActivity({
 251→          userId: agent.userId,
 252→          type: 'AGENT_CONVERSATION_STARTED',
 253→          targetName: agent.name,
 254→          targetType: 'agent',
 255→          agentId: agent.id,
 256→        });
 257→      }
 258→    }
 259→
 260→    // Fetch recent messages for context
 261→    const recentMessages = await prisma.message.findMany({
 262→      where: { conversationId: conversation.id },
 263→      orderBy: { createdAt: 'desc' },
 264→      take: agent.maxMessagesInContext,
 265→    });
 266→
 267→    // Reverse to get chronological order
 268→    recentMessages.reverse();
 269→
 270→    // Save user message
 271→    await prisma.message.create({
 272→      data: {
 273→        conversationId: conversation.id,
 274→        role: 'USER',
 275→        content: parsed.data.message,
 276→      },
 277→    });
 278→
 279→    // Build AI SDK messages from conversation history
 280→    const { streamText, stepCountIs } = await import('ai');
 281→
 282→    const messages: ModelMessage[] = [];
 283→
 284→    // Add system prompt if defined
 285→    if (agent.systemPrompt) {
 286→      messages.push({
 287→        role: 'system',
 288→        content: agent.systemPrompt,
 289→      });
 290→    }
 291→
 292→    // Build a set of tool call IDs that have corresponding tool results
 293→    // This is needed because AI SDK requires every tool call to have a matching tool result
 294→    const toolResultIds = new Set(
 295→      recentMessages.filter((m) => m.role === 'TOOL' && m.toolCallId).map((m) => m.toolCallId)
 296→    );
 297→
 298→    // Add conversation history - properly format for AI SDK
 299→    for (const msg of recentMessages) {
 300→      if (msg.role === 'USER') {
 301→        messages.push({ role: 'user', content: msg.content });
 302→      } else if (msg.role === 'ASSISTANT') {
 303→        // For assistant messages with tool calls, include ToolCallParts in content
 304→        if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
 305→          // Only include tool calls that have matching tool results
 306→          // AI SDK fails if there's a tool call without a corresponding tool result
 307→          const validToolCalls = (
 308→            msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
 309→          ).filter((tc) => toolResultIds.has(tc.toolCallId));
 310→
 311→          if (validToolCalls.length > 0) {
 312→            const toolCallParts = validToolCalls.map((tc) => ({
 313→              type: 'tool-call' as const,
 314→              toolCallId: tc.toolCallId,
 315→              toolName: tc.toolName,
 316→              input: tc.args,
 317→            }));
 318→            // Content includes text (if any) plus tool call parts
 319→            const content: Array<
 320→              | { type: 'text'; text: string }
 321→              | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
 322→            > = [];
 323→            if (msg.content) {
 324→              content.push({ type: 'text', text: msg.content });
 325→            }
 326→            content.push(...toolCallParts);
 327→            messages.push({
 328→              role: 'assistant',
 329→              content,
 330→            });
 331→          } else {
 332→            // All tool calls are missing results, just include text content
 333→            messages.push({
 334→              role: 'assistant',
 335→              content: msg.content || '',
 336→            });
 337→          }
 338→        } else {
 339→          messages.push({
 340→            role: 'assistant',
 341→            content: msg.content,
 342→          });
 343→        }
 344→      } else if (msg.role === 'TOOL') {
 345→        // Tool results use the 'tool' role with content array
 346→        messages.push({
 347→          role: 'tool',
 348→          content: [
 349→            {
 350→              type: 'tool-result' as const,
 351→              toolCallId: msg.toolCallId || '',
 352→              toolName: msg.toolName || '',
 353→              output: {
 354→                type: 'json' as const,
 355→                value: msg.toolResult,
 356→              },
 357→            },
 358→          ],
 359→        });
 360→      }
 361→    }
 362→
 363→    // Add new user message
 364→    messages.push({ role: 'user', content: parsed.data.message });
 365→
 366→    // Set up sandbox session if agent has sandbox enabled
 367→    let sessionId: string | undefined;
 368→    let _sandboxUrl: string | undefined;
 369→    let _sandboxApiKey: string | undefined;
 370→    if (agent.sandboxEnabled) {
 371→      const { getSandboxConfig, createSandboxSession } = await import('@/lib/executors');
 372→      const { url: sandboxUrl, apiKey: sandboxApiKey } = getSandboxConfig();
 373→      if (!sandboxUrl) {
 374→        return NextResponse.json(
 375→          {
 376→            success: false,
 377→            error: 'Sandbox not available. AGENT_SANDBOX_URL is not configured.',
 378→          },
 379→          { status: 502 }
 380→        );
 381→      }
 382→      _sandboxUrl = sandboxUrl;
 383→      _sandboxApiKey = sandboxApiKey;
 384→      sessionId = `${agent.id}:${conversationId}`;
 385→      try {
 386→        await createSandboxSession(sandboxUrl, sandboxApiKey, sessionId);
 387→      } catch (error) {
 388→        console.error('[Sandbox] Failed to create session:', error);
 389→        return NextResponse.json(
 390→          {
 391→            success: false,
 392→            error: `Failed to create sandbox session: ${error instanceof Error ? error.message : 'Unknown error'}`,
 393→          },
 394→          { status: 502 }
 395→        );
 396→      }
 397→    }
 398→
 399→    // Build tools from agent configuration
 400→    // Build tools - pass callerEnvVars if non-owner accessing public agent
 401→    const tools = buildAgentTools(agent, callerEnvVars, sessionId, _sandboxUrl, _sandboxApiKey);
 402→    const toolCount = Object.keys(tools).length;
 403→    const toolNames = Object.keys(tools);
 404→
 405→    console.log('[Agent] Built tools:', { toolCount, toolNames, agentId: agent.id });
 406→
 407→    // Get the provider model
 408→    const model = await getProviderModel(agent.provider, agent.modelId, apiKey);
 409→
 410→    // Create SSE stream
 411→    const stream = new ReadableStream({
 412→      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic
 413→      async start(controller) {
 414→        const encoder = new TextEncoder();
 415→
 416→        const sendEvent = (event: string, data: unknown) => {
 417→          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
 418→          controller.enqueue(encoder.encode(message));
 419→        };
 420→
 421→        // ML tracking: declared outside try so they're accessible in catch
 422→        const sequenceId = randomUUID();
 423→        const contextMessageCount = messages.length;
 424→        const contextTokenCount = Math.round(
 425→          messages.reduce((sum, m) => {
 426→            const content = typeof m.content === 'string' ? m.content : JSON.stringify(m.content);
 427→            return sum + content.length;
 428→          }, 0) / 4
 429→        );
 430→
 431→        try {
 432→          const startTime = Date.now();
 433→          let fullContent = '';
 434→          // Accumulate tool calls with their input args
 435→          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
 436→            new Map();
 437→          // Collect tool results to save AFTER assistant message (for correct chronological order)
 438→          const pendingToolResults: Array<{
 439→            toolCallId: string;
 440→            toolName: string;
 441→            output: unknown;
 442→          }> = [];
 443→          let inputTokens = 0;
 444→          let outputTokens = 0;
 445→          const streamErrors: string[] = [];
 446→          let turnIndex = 0;
 447→
 448→          // Send debug info so the client knows the stream configuration
 449→          sendEvent('debug', {
 450→            provider: agent.provider,
 451→            model: agent.modelId,
 452→            toolCount,
 453→            toolNames,
 454→            messageCount: messages.length,
 455→            sandboxEnabled: agent.sandboxEnabled,
 456→          });
 457→
 458→          // Stream the response with agentic loop control
 459→          const result = await streamText({
 460→            model,
 461→            messages,
 462→            tools,
 463→            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
 464→            onChunk: async ({ chunk }) => {
 465→              // Stream tool calls as they come in and capture their inputs
 466→              if (chunk.type === 'tool-call') {
 467→                const input = 'args' in chunk ? chunk.args : chunk.input;
 468→
 469→                // Log tool call for debugging
 470→                console.log('[Agent] Tool call initiated:', {
 471→                  toolName: chunk.toolName,
 472→                  toolCallId: chunk.toolCallId,
 473→                  input: JSON.stringify(input).slice(0, 500),
 474→                });
 475→
 476→                // Store tool call with input for later persistence
 477→                toolCallsMap.set(chunk.toolCallId, {
 478→                  toolCallId: chunk.toolCallId,
 479→                  toolName: chunk.toolName,
 480→                  args: input,
 481→                });
 482→                sendEvent('tool_call', {
 483→                  toolCallId: chunk.toolCallId,
 484→                  toolName: chunk.toolName,
 485→                  input,
 486→                });
 487→              }
 488→            },
 489→            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex callback
 490→            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
 491→              // Capture tool calls from step finish (backup in case onChunk missed any)
 492→              if (toolCalls && Array.isArray(toolCalls)) {
 493→                for (const tc of toolCalls) {
 494→                  if (!toolCallsMap.has(tc.toolCallId)) {
 495→                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
 496→                    const args =
 497→                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
 498→                    toolCallsMap.set(tc.toolCallId, {
 499→                      toolCallId: tc.toolCallId,
 500→                      toolName: tc.toolName,
 501→                      args,
 502→                    });
 503→                  }
 504→                }
 505→              }
 506→
 507→              // Send tool results via SSE but don't save yet (save after assistant message for correct order)
 508→              if (toolResults && toolResults.length > 0) {
 509→                for (const tr of toolResults) {
 510→                  // Check if this is an error result (AI SDK wraps errors in the output)
 511→                  const isError =
 512→                    tr.output && typeof tr.output === 'object' && 'error' in tr.output;
 513→
 514→                  // Log tool results for debugging
 515→                  if (isError) {
 516→                    console.error('[Agent] Tool execution failed:', {
 517→                      toolName: tr.toolName,
 518→                      toolCallId: tr.toolCallId,
 519→                      error: tr.output,
 520→                    });
 521→                  } else {
 522→                    console.log('[Agent] Tool execution success:', {
 523→                      toolName: tr.toolName,
 524→                      toolCallId: tr.toolCallId,
 525→                      outputPreview: JSON.stringify(tr.output).slice(0, 200),
 526→                    });
 527→                  }
 528→
 529→                  sendEvent('tool_result', {
 530→                    toolCallId: tr.toolCallId,
 531→                    output: tr.output,
 532→                    isError,
 533→                  });
 534→
 535→                  // Collect tool results to save after assistant message
 536→                  pendingToolResults.push({
 537→                    toolCallId: tr.toolCallId,
 538→                    toolName: tr.toolName,
 539→                    output: tr.output,
 540→                  });
 541→
 542→                  // Track each tool call execution event with ML training fields
 543→                  const toolCallArgs = toolCallsMap.get(tr.toolCallId)?.args;
 544→                  trackExecution({
 545→                    eventType: 'tool_call',
 546→                    source: 'agent_chat',
 547→                    userId: authResult.userId ?? undefined,
 548→                    apiKeyId: authResult.apiKeyId ?? undefined,
 549→                    agentId: agent.id,
 550→                    toolName: tr.toolName,
 551→                    status: isError ? 'error' : 'success',
 552→                    errorMessage:
 553→                      isError && tr.output && typeof tr.output === 'object' && 'error' in tr.output
 554→                        ? String((tr.output as { error: unknown }).error)
 555→                        : undefined,
 556→                    // ML training data
 557→                    sequenceId,
 558→                    turnIndex: turnIndex++,
 559→                    conversationId: conversation.id,
 560→                    inputArgs: toolCallArgs,
 561→                    outputSummary: tr.output,
 562→                    availableToolCount: toolCount,
 563→                    contextMessageCount,
 564→                    contextTokenCount,
 565→                  });
 566→                }
 567→              }
 568→
 569→              // Track token usage
 570→              if (usage) {
 571→                inputTokens += usage.inputTokens ?? 0;
 572→                outputTokens += usage.outputTokens ?? 0;
 573→              }
 574→            },
 575→          });
 576→
 577→          // Consume the full stream to catch errors that textStream silently swallows.
 578→          // The AI SDK's textStream only yields text chunks and hides provider errors,
 579→          // causing a generic "No output generated" when the actual error is e.g. a 401.
 580→          for await (const part of result.fullStream) {
 581→            if (part.type === 'text-delta') {
 582→              fullContent += part.text;
 583→              sendEvent('chunk', { type: 'text', text: part.text });
 584→            } else if (part.type === 'error') {
 585→              // This is the actual provider error (e.g. 401, 429, invalid model)
 586→              const streamError = part.error;
 587→              const errMsg =
 588→                streamError instanceof Error ? streamError.message : String(streamError);
 589→              streamErrors.push(errMsg);
 590→              console.error('[Agent] Stream error part:', streamError);
 591→              sendEvent('stream_error', {
 592→                message: errMsg,
 593→                raw: JSON.stringify(
 594→                  streamError,
 595→                  Object.getOwnPropertyNames(streamError || {})
 596→                ).slice(0, 2000),
 597→              });
 598→            }
 599→          }
 600→
 601→          // Get final response data (may throw NoOutputGeneratedError if stream had 0 steps)
 602→          let finalUsage: { inputTokens?: number; outputTokens?: number } | undefined;
 603→          try {
 604→            finalUsage = await result.usage;
 605→          } catch (usageError) {
 606→            // If usage rejects with NoOutputGeneratedError, the real error was already
 607→            // captured via the fullStream 'error' part above. Log but don't re-throw.
 608→            const cause =
 609→              usageError instanceof Error ? (usageError as { cause?: unknown }).cause : undefined;
 610→            const causeMsg =
 611→              cause instanceof Error ? cause.message : cause ? String(cause) : undefined;
 612→            if (causeMsg) streamErrors.push(causeMsg);
 613→            console.warn('[Agent] Usage rejected (stream produced 0 steps):', {
 614→              error: usageError instanceof Error ? usageError.message : String(usageError),
 615→              cause: causeMsg,
 616→            });
 617→          }
 618→
 619→          // Convert tool calls map to array for storage
 620→          const allToolCalls = Array.from(toolCallsMap.values());
 621→
 622→          // Update token counts from final usage
 623→          if (finalUsage) {
 624→            inputTokens = finalUsage.inputTokens ?? inputTokens;
 625→            outputTokens = finalUsage.outputTokens ?? outputTokens;
 626→          }
 627→
 628→          // If there were stream errors and no content, save errors as the content
 629→          const savedContent =
 630→            fullContent ||
 631→            (streamErrors.length > 0 ? `[Stream Error] ${streamErrors.join('\n')}` : '');
 632→
 633→          // Save assistant message FIRST (so it has earlier createdAt than tool results)
 634→          const assistantMessage = await prisma.message.create({
 635→            data: {
 636→              conversationId: conversation.id,
 637→              role: 'ASSISTANT',
 638→              content: savedContent,
 639→              // Cast to Prisma-compatible JSON type
 640→              toolCalls:
 641→                allToolCalls.length > 0
 642→                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
 643→                  : Prisma.JsonNull,
 644→              inputTokens,
 645→              outputTokens,
 646→              // ML training data
 647→              availableToolCount: toolCount,
 648→              availableToolNames: toolNames as unknown as Prisma.InputJsonValue,
 649→              sequenceId,
 650→              contextMessageCount,
 651→              contextTokenCount,
 652→            },
 653→          });
 654→
 655→          // Now save TOOL messages (after assistant, for correct chronological order)
 656→          for (const tr of pendingToolResults) {
 657→            await prisma.message.create({
 658→              data: {
 659→                conversationId: conversation.id,
 660→                role: 'TOOL',
 661→                content: JSON.stringify(tr.output),
 662→                toolCallId: tr.toolCallId,
 663→                toolName: tr.toolName,
 664→                toolResult: tr.output as object,
 665→              },
 666→            });
 667→          }
 668→
 669→          // Update conversation timestamp
 670→          await prisma.conversation.update({
 671→            where: { id: conversation.id },
 672→            data: { updatedAt: new Date() },
 673→          });
 674→
 675→          const executionTimeMs = Date.now() - startTime;
 676→
 677→          // Send token usage
 678→          sendEvent('tokens', {
 679→            inputTokens,
 680→            outputTokens,
 681→            totalTokens: inputTokens + outputTokens,
 682→          });
 683→
 684→          // Warn if the response was completely empty (no text, no tool calls)
 685→          if (!fullContent && allToolCalls.length === 0) {
 686→            const streamErrorSummary =
 687→              streamErrors.length > 0 ? `\nStream errors: ${streamErrors.join('; ')}` : '';
 688→            console.warn('[Agent] Empty response from model:', {
 689→              agentId: agent.id,
 690→              provider: agent.provider,
 691→              model: agent.modelId,
 692→              toolCount,
 693→              messageCount: messages.length,
 694→              inputTokens,
 695→              outputTokens,
 696→              streamErrors,
 697→            });
 698→            sendEvent('warning', {
 699→              type: 'empty_response',
 700→              message: `Model returned no text and made no tool calls.${streamErrorSummary} Provider: ${agent.provider}, Model: ${agent.modelId}, Tools: ${toolCount}`,
 701→              debug: {
 702→                inputTokens,
 703→                outputTokens,
 704→                toolCount,
 705→                provider: agent.provider,
 706→                model: agent.modelId,
 707→                streamErrors,
 708→              },
 709→            });
 710→          }
 711→
 712→          // Send completion event
 713→          sendEvent('complete', {
 714→            messageId: assistantMessage.id,
 715→            conversationId: conversation.id,
 716→            executionTimeMs,
 717→            hasContent: !!fullContent,
 718→            toolCallCount: allToolCalls.length,
 719→          });
 720→
 721→          // Track agent run execution event
 722→          trackExecution({
 723→            eventType: 'agent_run',
 724→            source: 'agent_chat',
 725→            userId: authResult.userId ?? undefined,
 726→            apiKeyId: authResult.apiKeyId ?? undefined,
 727→            agentId: agent.id,
 728→            status: 'success',
 729→            durationMs: executionTimeMs,
 730→            tokensIn: inputTokens,
 731→            tokensOut: outputTokens,
 732→            // ML training data
 733→            sequenceId,
 734→            conversationId: conversation.id,
 735→            availableToolCount: toolCount,
 736→            contextMessageCount,
 737→            contextTokenCount,
 738→          });
 739→
 740→          // Track usage
 741→          if (authResult.userId) {
 742→            trackUsage({
 743→              apiKeyId: authResult.apiKeyId ?? undefined,
 744→              userId: authResult.userId,
 745→              endpoint: `/api/agents/${agentId}/conversation/${conversationId}`,
 746→              method: 'POST',
 747→              statusCode: 200,
 748→              latencyMs: executionTimeMs,
 749→              resourceType: 'agent',
 750→              resourceId: agentId,
 751→              tokensIn: inputTokens,
 752→              tokensOut: outputTokens,
 753→              model: agent.modelId,
 754→            });
 755→          }
 756→        } catch (error) {
 757→          // Extract rich error details from provider SDK errors
 758→          const errorMessage = error instanceof Error ? error.message : String(error);
 759→          const errorStack = error instanceof Error ? error.stack : undefined;
 760→
 761→          // In production, class names get minified (e.g. "aB" instead of "APICallError").
 762→          // Try to infer the real error type from its properties.
 763→          const err = error as Record<string, unknown>;
 764→          const inferredType =
 765→            err.statusCode || err.responseBody
 766→              ? 'APICallError'
 767→              : err.url && err.requestBodyValues
 768→                ? 'APIRequestError'
 769→                : error instanceof Error
 770→                  ? error.constructor.name
 771→                  : 'UnknownError';
 772→
 773→          // AI SDK and provider errors often have additional properties
 774→          const errorDetails: Record<string, unknown> = {
 775→            type: inferredType,
 776→            message: errorMessage,
 777→            agentId: agent.id,
 778→            provider: agent.provider,
 779→            model: agent.modelId,
 780→            toolCount,
 781→          };
 782→
 783→          // Extract HTTP status and response body from provider errors
 784→          // @ai-sdk/openai errors have statusCode, responseBody, etc.
 785→          if (err.statusCode) errorDetails.statusCode = err.statusCode;
 786→          if (err.status) errorDetails.status = err.status;
 787→          if (err.responseBody) errorDetails.responseBody = String(err.responseBody).slice(0, 1000);
 788→          if (err.url) errorDetails.url = err.url;
 789→          if (err.requestBodyValues)
 790→            errorDetails.requestBodyValues = JSON.stringify(err.requestBodyValues).slice(0, 500);
 791→          if (err.cause) {
 792→            const cause = err.cause as Record<string, unknown>;
 793→            errorDetails.cause = cause.message || String(err.cause);
 794→            if (cause.code) errorDetails.causeCode = cause.code;
 795→          }
 796→          if (err.data) errorDetails.data = err.data;
 797→          if (err.responseHeaders)
 798→            errorDetails.responseHeaders = JSON.stringify(err.responseHeaders).slice(0, 500);
 799→
 800→          // Log full error for server debugging
 801→          console.error('[Agent] Conversation stream error:', {
 802→            error: errorMessage,
 803→            stack: errorStack,
 804→            ...errorDetails,
 805→          });
 806→
 807→          // Save error as an ASSISTANT message so it appears in conversation history and JSON export
 808→          try {
 809→            await prisma.message.create({
 810→              data: {
 811→                conversationId: conversation.id,
 812→                role: 'ASSISTANT',
 813→                content: `[Error] ${errorMessage}`,
 814→                toolCalls: Prisma.JsonNull,
 815→                inputTokens: 0,
 816→                outputTokens: 0,
 817→              },
 818→            });
 819→          } catch (saveErr) {
 820→            console.error('[Agent] Failed to save error message:', saveErr);
 821→          }
 822→
 823→          // Send rich error event to client
 824→          sendEvent('error', {
 825→            message: errorMessage,
 826→            type: inferredType,
 827→            details: errorDetails,
 828→          });
 829→
 830→          // Track agent run error with ML training data
 831→          const errMsg = error instanceof Error ? error.message : 'Unknown error';
 832→          const errStatusCode = typeof err.statusCode === 'number' ? err.statusCode : undefined;
 833→          trackExecution({
 834→            eventType: 'agent_run',
 835→            source: 'agent_chat',
 836→            userId: authResult.userId ?? undefined,
 837→            apiKeyId: authResult.apiKeyId ?? undefined,
 838→            agentId: agent.id,
 839→            status: 'error',
 840→            durationMs: Date.now() - startTime,
 841→            errorMessage: errMsg,
 842→            errorCategory: inferErrorCategory({
 843→              errorMessage: errMsg,
 844→              statusCode: errStatusCode,
 845→            }),
 846→            // ML training data
 847→            sequenceId,
 848→            conversationId: conversation.id,
 849→            availableToolCount: toolCount,
 850→            contextMessageCount,
 851→            contextTokenCount,
 852→          });
 853→
 854→          // Update conversation status to error
 855→          prisma.conversation
 856→            .update({
 857→              where: { id: conversation.id },
 858→              data: { status: 'error' },
 859→            })
 860→            .catch(() => {});
 861→
 862→          // Track error
 863→          if (authResult.userId) {
 864→            trackUsage({
 865→              apiKeyId: authResult.apiKeyId ?? undefined,
 866→              userId: authResult.userId,
 867→              endpoint: `/api/agents/${agentId}/conversation/${conversationId}`,
 868→              method: 'POST',
 869→              statusCode: 500,
 870→              latencyMs: Date.now() - startTime,
 871→              resourceType: 'agent',
 872→              resourceId: agentId,
 873→              errorCode: 'STREAM_ERROR',
 874→              errorMessage: error instanceof Error ? error.message : 'Unknown error',
 875→            });
 876→          }
 877→        } finally {
 878→          controller.close();
 879→        }
 880→      },
 881→    });
 882→
 883→    return new NextResponse(stream, {
 884→      headers: {
 885→        'Content-Type': 'text/event-stream',
 886→        'Cache-Control': 'no-cache',
 887→        Connection: 'keep-alive',
 888→      },
 889→    });
 890→  } catch (error) {
 891→    console.error('Failed to process message:', error);
 892→    return NextResponse.json(
 893→      {
 894→        success: false,
 895→        error: error instanceof Error ? error.message : 'Failed to process message',
 896→      },
 897→      { status: 500 }
 898→    );
 899→  }
 900→}
 901→
 902→/**
 903→ * GET /api/agents/[id]/conversation/[conversationId]
 904→ * Retrieve conversation history with pagination
 905→ *
 906→ * Query params:
 907→ * - limit: Max messages to return (default: 50, max: 100)
 908→ * - before: Fetch messages created before this ISO timestamp (for loading older messages)
 909→ * - after: Fetch messages created after this ISO timestamp (for loading newer messages)
 910→ * - format: 'json' for full debug view (no pagination, includes agent info)
 911→ *
 912→ * Default behavior (no before/after): Returns the most recent messages
 913→ * With before: Returns messages older than the timestamp (for scrolling up)
 914→ * With after: Returns messages newer than the timestamp (for refreshing)
 915→ */
 916→export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
 917→  const { id: agentId, conversationId } = await context.params;
 918→  const { searchParams } = new URL(request.url);
 919→
 920→  const format = searchParams.get('format');
 921→  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
 922→  const before = searchParams.get('before');
 923→  const after = searchParams.get('after');
 924→
 925→  try {
 926→    // Fetch agent by ID with more details for JSON format
 927→    const agent = await prisma.agent.findUnique({
 928→      where: { id: agentId },
 929→      select: {
 930→        id: true,
 931→        uid: true,
 932→        name: true,
 933→        provider: true,
 934→        modelId: true,
 935→        sandboxEnabled: true,
 936→        executorType: true,
 937→        executorConfig: true,
 938→      },
 939→    });
 940→
 941→    if (!agent) {
 942→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
 943→    }
 944→
 945→    // Fetch conversation
 946→    const conversation = await prisma.conversation.findUnique({
 947→      where: {
 948→        agentId_slug: {
 949→          agentId: agent.id,
 950→          slug: conversationId,
 951→        },
 952→      },
 953→    });
 954→
 955→    if (!conversation) {
 956→      return NextResponse.json(
 957→        { success: false, error: 'Conversation not found' },
 958→        { status: 404 }
 959→      );
 960→    }
 961→
 962→    // For JSON format, return all messages with full details
 963→    if (format === 'json') {
 964→      const allMessages = await prisma.message.findMany({
 965→        where: { conversationId: conversation.id },
 966→        orderBy: { createdAt: 'asc' },
 967→      });
 968→
 969→      const response = {
 970→        _meta: {
 971→          exportedAt: new Date().toISOString(),
 972→          format: 'tpmjs-conversation-log',
 973→          version: '1.0',
 974→        },
 975→        agent: {
 976→          id: agent.id,
 977→          uid: agent.uid,
 978→          name: agent.name,
 979→          provider: agent.provider,
 980→          modelId: agent.modelId,
 981→          executorType: agent.executorType,
 982→          executorConfig: agent.executorConfig,
 983→        },
 984→        conversation: {
 985→          id: conversation.id,
 986→          slug: conversation.slug,
 987→          title: conversation.title,
 988→          status: conversation.status,
 989→          createdAt: conversation.createdAt,
 990→          updatedAt: conversation.updatedAt,
 991→          messageCount: allMessages.length,
 992→        },
 993→        messages: allMessages.map((m) => ({
 994→          id: m.id,
 995→          role: m.role,
 996→          content: m.content,
 997→          toolCalls: m.toolCalls,
 998→          toolCallId: m.toolCallId,
 999→          toolName: m.toolName,
1000→          toolResult: m.toolResult,
1001→          inputTokens: m.inputTokens,
1002→          outputTokens: m.outputTokens,
1003→          // ML training fields
1004→          availableToolCount: m.availableToolCount,
1005→          availableToolNames: m.availableToolNames,
1006→          sequenceId: m.sequenceId,
1007→          contextMessageCount: m.contextMessageCount,
1008→          contextTokenCount: m.contextTokenCount,
1009→          createdAt: m.createdAt,
1010→        })),
1011→        stats: {
1012→          totalMessages: allMessages.length,
1013→          userMessages: allMessages.filter((m) => m.role === 'USER').length,
1014→          assistantMessages: allMessages.filter((m) => m.role === 'ASSISTANT').length,
1015→          toolResults: allMessages.filter((m) => m.role === 'TOOL').length,
1016→          totalInputTokens: allMessages.reduce((sum, m) => sum + (m.inputTokens || 0), 0),
1017→          totalOutputTokens: allMessages.reduce((sum, m) => sum + (m.outputTokens || 0), 0),
1018→        },
1019→      };
1020→
1021→      // Return pretty-printed JSON with proper content type
1022→      return new NextResponse(JSON.stringify(response, null, 2), {
1023→        headers: {
1024→          'Content-Type': 'application/json',
1025→          'Content-Disposition': `inline; filename="${conversation.slug}-logs.json"`,
1026→        },
1027→      });
1028→    }
1029→
1030→    // Standard paginated response
1031→    const whereClause: {
1032→      conversationId: string;
1033→      createdAt?: { lt?: Date; gt?: Date };
1034→    } = { conversationId: conversation.id };
1035→
1036→    if (before) {
1037→      whereClause.createdAt = { lt: new Date(before) };
1038→    } else if (after) {
1039→      whereClause.createdAt = { gt: new Date(after) };
1040→    }
1041→
1042→    // Determine fetch order:
1043→    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
1044→    // - "after": Fetch asc (oldest first) to get messages after the cursor
1045→    const shouldFetchDesc = !after;
1046→
1047→    // Fetch messages
1048→    const messages = await prisma.message.findMany({
1049→      where: whereClause,
1050→      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
1051→      take: limit + 1,
1052→    });
1053→
1054→    const hasMore = messages.length > limit;
1055→    let paginatedMessages = hasMore ? messages.slice(0, limit) : messages;
1056→
1057→    // Reverse if we fetched in desc order to maintain chronological order
1058→    if (shouldFetchDesc) {
1059→      paginatedMessages = paginatedMessages.reverse();
1060→    }
1061→
1062→    const mappedMessages = paginatedMessages.map((m) => ({
1063→      id: m.id,
1064→      role: m.role,
1065→      content: m.content,
1066→      toolCalls: m.toolCalls,
1067→      toolCallId: m.toolCallId,
1068→      toolName: m.toolName,
1069→      toolResult: m.toolResult,
1070→      inputTokens: m.inputTokens,
1071→      outputTokens: m.outputTokens,
1072→      availableToolCount: m.availableToolCount,
1073→      availableToolNames: m.availableToolNames,
1074→      sequenceId: m.sequenceId,
1075→      contextMessageCount: m.contextMessageCount,
1076→      contextTokenCount: m.contextTokenCount,
1077→      createdAt: m.createdAt,
1078→    }));
1079→
1080→    return NextResponse.json({
1081→      success: true,
1082→      data: {
1083→        id: conversation.id,
1084→        slug: conversation.slug,
1085→        title: conversation.title,
1086→        createdAt: conversation.createdAt,
1087→        updatedAt: conversation.updatedAt,
1088→        messages: mappedMessages,
1089→      },
1090→      pagination: {
1091→        limit,
1092→        hasMore,
1093→        ...(before && { before }),
1094→        ...(after && { after }),
1095→      },
1096→    });
1097→  } catch (error) {
1098→    console.error('Failed to fetch conversation:', error);
1099→    return NextResponse.json(
1100→      { success: false, error: 'Failed to fetch conversation' },
1101→      { status: 500 }
1102→    );
1103→  }
1104→}
