1107→ * DELETE /api/agents/[id]/conversation/[conversationId]
1108→ * Delete a conversation
1109→ */
1110→export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
1111→  const { id: agentId, conversationId } = await context.params;
1112→
1113→  try {
1114→    // Fetch agent by ID (include sandboxEnabled for cleanup)
1115→    const agent = await prisma.agent.findUnique({
1116→      where: { id: agentId },
1117→      select: { id: true, sandboxEnabled: true },
1118→    });
1119→
1120→    if (!agent) {
1121→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
1122→    }
1123→
1124→    // Destroy sandbox session if applicable (fire-and-forget)
1125→    if (agent.sandboxEnabled) {
1126→      const { getSandboxConfig, destroySandboxSession } = await import('@/lib/executors');
1127→      const { url: sandboxUrl, apiKey: sandboxApiKey } = getSandboxConfig();
1128→      if (sandboxUrl) {
