 10→export const maxDuration = 60;
 11→
 12→// BM25 parameters
 13→const k1 = 1.5; // term frequency saturation parameter
 14→const b = 0.75; // length normalization parameter
 15→
 16→// Split camelCase and PascalCase into words
 17→function splitCamelCase(text: string): string {
 18→  return text
 19→    .replace(/([a-z])([A-Z])/g, '$1 $2') // camelCase -> camel Case
 20→    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2'); // XMLParser -> XML Parser
 21→}
 22→
 23→// Tokenize text into words (handles camelCase)
 24→function tokenize(text: string): string[] {
 25→  return splitCamelCase(text)
 26→    .toLowerCase()
 27→    .replace(/[^\w\s]/g, ' ')
 28→    .split(/\s+/)
 29→    .filter((t) => t.length > 0);
 30→}
 31→
 32→// Check for exact tool name match (case-insensitive)
 33→function hasExactNameMatch(query: string, toolName: string): boolean {
 34→  const queryLower = query.toLowerCase();
 35→  const nameLower = toolName.toLowerCase();
 36→  return queryLower.includes(nameLower) || nameLower.includes(queryLower);
 37→}
 38→
 39→// Check for package name match (case-insensitive)
 40→function hasPackageNameMatch(query: string, packageName: string): boolean {
 41→  const queryLower = query.toLowerCase();
 42→  const packageLower = packageName.toLowerCase();
 43→  // Check if query contains package name or package name contains query
 44→  // Also handle partial matches like "@tpmjs/tools-" matching "@tpmjs/tools-unsandbox"
 45→  return queryLower.includes(packageLower) || packageLower.includes(queryLower);
 46→}
 47→
 48→// Calculate term frequency
 49→function termFrequency(term: string, tokens: string[]): number {
 50→  return tokens.filter((t) => t === term).length;
 51→}
 52→
 53→// Calculate BM25 score
 54→function calculateBM25(
 55→  query: string,
 56→  document: string,
 57→  avgDocLength: number,
 58→  totalDocs: number,
 59→  docFrequencies: Map<string, number>
 60→): number {
 61→  const queryTokens = tokenize(query);
 62→  const docTokens = tokenize(document);
 63→  const docLength = docTokens.length;
 64→
 65→  let score = 0;
 66→
 67→  for (const term of queryTokens) {
 68→    const tf = termFrequency(term, docTokens);
 69→    if (tf === 0) continue;
 70→
 71→    // IDF calculation
 72→    const docFreq = docFrequencies.get(term) || 0;
 73→    const idf = Math.log((totalDocs - docFreq + 0.5) / (docFreq + 0.5) + 1);
 74→
 75→    // BM25 formula
 76→    const numerator = tf * (k1 + 1);
 77→    const denominator = tf + k1 * (1 - b + b * (docLength / avgDocLength));
 78→
 79→    score += idf * (numerator / denominator);
 80→  }
 81→
 82→  return score;
 83→}
