 99→        {
100→          status: 429,
101→          headers: getRateLimitHeaders(rateResult),
102→        }
103→      );
104→    }
105→  } else {
106→    const rateLimitResponse = checkRateLimit(request, STRICT_RATE_LIMIT);
107→    if (rateLimitResponse) return rateLimitResponse;
108→  }
