 56→  input?: unknown;
 57→  output?: unknown;
 58→  status: 'pending' | 'running' | 'success' | 'error';
 59→}
 60→
 61→/**
 62→ * Check if a tool output contains an error
 63→ */
 64→function isToolError(output: unknown): boolean {
 65→  if (!output || typeof output !== 'object') return false;
 66→  const obj = output as Record<string, unknown>;
 67→  return (
 68→    obj.success === false ||
 69→    obj.error !== undefined ||
 70→    obj.__tpmjs_error__ !== undefined ||
 71→    (typeof obj.message === 'string' && obj.message.toLowerCase().includes('error'))
 72→  );
 73→}
 74→
 75→/**
 76→ * Extract error message from tool output
 77→ */
 78→function getErrorMessage(output: unknown): string | null {
 79→  if (!output || typeof output !== 'object') return null;
 80→  const obj = output as Record<string, unknown>;
 81→  if (typeof obj.error === 'string') return obj.error;
 82→  if (typeof obj.__tpmjs_error__ === 'string') return obj.__tpmjs_error__;
 83→  if (obj.success === false && typeof obj.message === 'string') return obj.message;
 84→  return null;
 85→}
 86→
 87→/**
 88→ * Tool call card with style guide aesthetics
 89→ */
 90→function ToolCallCard({
 91→  toolCall,
 92→  isExpanded,
 93→  onToggle,
 94→}: {
 95→  toolCall: ToolCall;
 96→  isExpanded: boolean;
 97→  onToggle: () => void;
 98→}) {
 99→  const hasError = Boolean(toolCall.output && isToolError(toolCall.output));
100→  const errorMessage = hasError ? getErrorMessage(toolCall.output) : null;
101→  const effectiveStatus = hasError ? 'error' : toolCall.status;
102→
