375→  const handleSend = async () => {
376→    if (!input.trim() || !agent || isSending) return;
377→
378→    const messageContent = input.trim();
379→    setInput('');
380→    setIsSending(true);
381→    setStreamingContent('');
382→    setError(null);
383→    setErrorDetails(null);
384→    setDebugInfo(null);
385→    setWarnings([]);
386→    setToolCalls([]);
387→
388→    const conversationId = activeConversationId || chatId;
389→
390→    // Optimistically add user message
391→    const userMessage: Message = {
392→      id: `temp-${Date.now()}`,
393→      role: 'USER',
394→      content: messageContent,
395→      createdAt: new Date().toISOString(),
396→    };
397→    setMessages((prev) => [...prev, userMessage]);
398→
399→    try {
400→      const response = await fetch(`/api/agents/${agentId}/conversation/${conversationId}`, {
401→        method: 'POST',
402→        headers: { 'Content-Type': 'application/json' },
403→        body: JSON.stringify({ message: messageContent }),
404→      });
405→
406→      if (!response.ok) {
407→        const errorData = await response.json();
408→        throw new Error(errorData.error || 'Failed to send message');
409→      }
410→
411→      // Handle SSE stream
412→      const reader = response.body?.getReader();
413→      if (!reader) throw new Error('No response body');
414→
415→      const decoder = new TextDecoder();
416→      let buffer = '';
417→
418→      while (true) {
419→        const { done, value } = await reader.read();
420→        if (done) break;
421→
422→        buffer += decoder.decode(value, { stream: true });
423→
424→        // Parse SSE events
425→        const lines = buffer.split('\n');
426→        buffer = lines.pop() || '';
427→
428→        let eventType = '';
429→        for (const line of lines) {
430→          if (line.startsWith('event: ')) {
431→            eventType = line.slice(7);
432→          } else if (line.startsWith('data: ')) {
433→            const data = JSON.parse(line.slice(6));
434→
435→            switch (eventType) {
436→              case 'debug':
437→                setDebugInfo(data);
438→                console.log('[Agent Chat] Stream debug:', data);
439→                break;
440→              case 'warning':
441→                setWarnings((prev) => [...prev, data.message]);
442→                console.warn('[Agent Chat] Stream warning:', data);
443→                break;
444→              case 'stream_error':
445→                // Actual provider error surfaced from the AI SDK fullStream
446→                console.error('[Agent Chat] Provider stream error:', data);
447→                setErrorDetails((prev) => ({ ...prev, streamError: data }));
448→                setWarnings((prev) => [...prev, `Provider error: ${data.message}`]);
449→                break;
450→              case 'chunk':
451→                setStreamingContent((prev) => prev + data.text);
452→                break;
453→              case 'tool_call':
454→                setToolCalls((prev) => [
455→                  ...prev,
456→                  {
457→                    toolCallId: data.toolCallId,
458→                    toolName: data.toolName,
459→                    input: data.input,
460→                    status: 'running',
461→                  },
462→                ]);
463→                setExpandedToolCalls((prev) => new Set([...prev, data.toolCallId]));
464→                break;
465→              case 'tool_result':
466→                setToolCalls((prev) =>
467→                  prev.map((tc) =>
468→                    tc.toolCallId === data.toolCallId
469→                      ? { ...tc, output: data.output, status: 'success' as const }
470→                      : tc
471→                  )
472→                );
473→                break;
474→              case 'complete':
475→                await fetchMessages();
476→                await fetchConversations();
477→                setStreamingContent('');
478→                setToolCalls([]);
479→                break;
480→              case 'tokens':
481→                console.log('[Agent Chat] Token usage:', data);
482→                break;
483→              case 'error': {
484→                // Store structured error details for display
485→                const details = data.details || {};
486→                setErrorDetails(details);
487→                console.error('[Agent Chat] Stream error:', data);
488→                throw new Error(data.message);
489→              }
490→            }
491→          }
492→        }
493→      }
494→    } catch (err) {
495→      console.error('Failed to send message:', err);
496→      setError(err instanceof Error ? err.message : 'Failed to send message');
497→      setMessages((prev) => prev.filter((m) => m.id !== userMessage.id));
498→    } finally {
499→      setIsSending(false);
500→      setStreamingContent('');
501→      inputRef.current?.focus();
502→    }
503→  };
504→
505→  const handleKeyDown = (e: React.KeyboardEvent) => {
