693→
694→            {(() => {
695→              // Build a map of toolCallId -> tool result from TOOL messages
696→              const toolResultsMap = new Map<string, unknown>();
697→              for (const msg of messages) {
698→                if (msg.role === 'TOOL' && msg.toolCallId) {
