    {/* Tool Permissions */}
    <div className="bg-surface border border-border rounded-lg p-6">
      <h3 className="text-lg font-medium text-foreground mb-1">Tool Permissions</h3>
      <p className="text-sm text-foreground-secondary mb-4">
        Control which tools the agent can use. Denied tools are hidden from the model. Tools set
        to &quot;ask&quot; require user approval before execution.
      </p>
      <ToolPermissionsEditor
        permissions={agent.toolPermissions as import('@tpmjs/types/agent').ToolPermissions | null}
        onChange={async (newPermissions) => {
          try {
            const response = await fetch(`/api/agents/${agentId}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ toolPermissions: newPermissions }),
            });
            const result = await response.json();
            if (result.success) {
              setAgent((prev) => prev ? { ...prev, toolPermissions: newPermissions } : prev);
            } else {
              alert(`Failed to save permissions: ${result.error || 'Unknown error'}`);
            }
          } catch {
            alert('Failed to save permissions. Please try again.');
          }
        }}
        toolNames={agentTools.map((t) =>
          `${t.tool.npmPackageName}-${t.tool.name}`
            .replace(/[@/]/g, '-')
            .replace(/^-+/, '')
            .slice(0, 64)
        )}
      />
    </div>

    {/* Dynamic Tool Discovery */}
    <div className="bg-surface border border-border rounded-lg p-6">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-medium text-foreground mb-1">Dynamic Tool Discovery</h3>
          <p className="text-sm text-foreground-secondary">
            Start with a <code className="font-mono text-xs bg-surface-secondary px-1 py-0.5 rounded">searchTools</code> meta-tool
            instead of loading all tools upfront. Reduces context usage for agents with many tools.
          </p>
        </div>
        <Switch
          checked={agent.dynamicToolDiscovery}
          onCheckedChange={async (checked) => {
            try {
              const response = await fetch(`/api/agents/${agentId}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ dynamicToolDiscovery: checked }),
              });
              const result = await response.json();
              if (result.success) {
                setAgent((prev) => prev ? { ...prev, dynamicToolDiscovery: checked } : prev);
              } else {
                alert(`Failed to save: ${result.error || 'Unknown error'}`);
              }
            } catch {
              alert('Failed to save. Please try again.');
            }
          }}
        />
      </div>
    </div>
  </div>
)}

