 12→/**
 13→ * Parse the URL slug to extract package name and optional tool name
 14→ */
 15→function parseSlug(slug: string[]): { packageName: string; toolName?: string } {
 16→  // URL-decode slug components (@ comes as %40)
 17→  const decodedSlug = slug.map((s) => decodeURIComponent(s));
 18→
 19→  if (decodedSlug[0]?.startsWith('@')) {
 20→    // Scoped package: ['@scope', 'package', 'toolName?']
 21→    const packageName = decodedSlug.slice(0, 2).join('/');
 22→    const toolName = decodedSlug[2];
 23→    return { packageName, toolName };
 24→  }
 25→  // Unscoped: ['package', 'toolName?']
 26→  return { packageName: decodedSlug[0] || '', toolName: decodedSlug[1] };
 27→}
 28→
 29→/**
 30→ * Fetch tool data from database
 31→ */
 32→async function getTool(slug: string[]): Promise<Tool | null> {
 33→  const { packageName, toolName } = parseSlug(slug);
 34→
 35→  if (!packageName) {
 36→    return null;
 37→  }
 38→
 39→  // First find the package by npm name
 40→  const pkg = await prisma.package.findUnique({
 41→    where: { npmPackageName: packageName },
 42→  });
 43→
 44→  if (!pkg) {
 45→    return null;
 46→  }
 47→
 48→  // Then find the tool using packageId
 49→  const tool = await prisma.tool.findFirst({
 50→    where: {
 51→      packageId: pkg.id,
 52→      ...(toolName && { name: toolName }),
 53→    },
 54→    include: {
 55→      package: true,
