 63→
 64→  // Transform Prisma result to Tool interface
 65→  return {
 66→    id: tool.id,
 67→    name: tool.name,
 68→    description: tool.description,
 69→    parameters: tool.parameters as Tool['parameters'],
 70→    inputSchema: tool.inputSchema as Tool['inputSchema'],
