101→      npmAuthor: tool.package.npmAuthor as Tool['package']['npmAuthor'],
102→      npmMaintainers: tool.package.npmMaintainers as Tool['package']['npmMaintainers'],
103→      npmLicense: tool.package.npmLicense,
104→      githubStars: tool.package.githubStars,
