 25→
 26→type SortOption = 'downloads' | 'likes' | 'recent' | 'name';
 27→
 28→function formatDownloads(count: number): string {
 29→  if (count >= 1000000) return `${(count / 1000000).toFixed(1)}M`;
 30→  if (count >= 1000) return `${(count / 1000).toFixed(1)}k`;
 31→  return count.toString();
 32→}
 33→
 34→function truncateText(text: string, maxLength: number): string {
 35→  if (text.length <= maxLength) return text;
 36→  return `${text.slice(0, maxLength).trim()}...`;
 37→}
 38→
 39→/** Sort tools by criterion, pushing broken tools to the bottom */
 40→function sortTools(tools: Tool[], sortBy: SortOption): Tool[] {
 41→  return [...tools].sort((a, b) => {
 42→    const aIsBroken = a.importHealth === 'BROKEN' || a.executionHealth === 'BROKEN';
 43→    const bIsBroken = b.importHealth === 'BROKEN' || b.executionHealth === 'BROKEN';
 44→    // Always push broken tools to bottom
 45→    if (aIsBroken && !bIsBroken) return 1;
 46→    if (!aIsBroken && bIsBroken) return -1;
 47→
 48→    // Within same broken status, sort by selected criterion
 49→    switch (sortBy) {
 50→      case 'downloads': {
 51→        const aDownloads = a.package.npmDownloadsLastMonth ?? 0;
 52→        const bDownloads = b.package.npmDownloadsLastMonth ?? 0;
 53→        return bDownloads - aDownloads;
 54→      }
 55→      case 'likes': {
 56→        const aLikes = a.likeCount ?? 0;
 57→        const bLikes = b.likeCount ?? 0;
 58→        return bLikes - aLikes;
 59→      }
 60→      case 'recent': {
 61→        const aTime = a.createdAt ? new Date(a.createdAt).getTime() : 0;
 62→        const bTime = b.createdAt ? new Date(b.createdAt).getTime() : 0;
 63→        return bTime - aTime;
 64→      }
 65→      case 'name': {
 66→        const aName = a.name.toLowerCase();
 67→        const bName = b.name.toLowerCase();
 68→        return aName.localeCompare(bName);
 69→      }
 70→      default:
 71→        return 0;
 72→    }
 73→  });
 74→}
