        type="application/ld+json"
        // biome-ignore lint/security/noDangerouslySetInnerHtml: required for structured data ld+json
        dangerouslySetInnerHTML={{ __html: JSON.stringify(softwareApplicationSchema) }}
      />
      <AppHeader />

      {/* Main content */}
      <Container size="xl" padding="md" className="py-8">
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-sm text-foreground-secondary mb-6">
          <Link href="/" className="hover:text-foreground">
            Home
