import type { ButtonHTMLAttributes } from 'react';

/**
 * Switch component props
 */
export interface SwitchProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'onChange' | 'type'> {
  /**
   * Controlled checked state
   */
  checked?: boolean;

  /**
   * Default checked state for uncontrolled mode
   * @default false
   */
  defaultChecked?: boolean;

  /**
   * Change handler (receives new checked state)
   */
  onChange?: (checked: boolean) => void;

  /**
   * Visual state of the switch
   * @default 'default'
   */
  state?: 'default' | 'error' | 'success';

  /**
   * Size variant
   * @default 'md'
   */
  size?: 'sm' | 'md' | 'lg';

  /**
   * Optional label text
   */
  label?: string;

  /**
   * Label position relative to switch
   * @default 'right'
   */
  labelPosition?: 'left' | 'right';

  /**
   * Loading state (shows spinner, disables interaction)
   * @default false
   */
  loading?: boolean;

  /**
   * Name for form submission
   */
  name?: string;

  /**
   * Value for form submission when checked
   */
  value?: string;
}

/**
 * Switch ref type
 */
export type SwitchRef = HTMLButtonElement;

import type { SelectHTMLAttributes } from 'react';

/**
 * Option for Select component
 */
export interface SelectOption {
  /**
   * Option value
   */
  value: string;

  /**
   * Option label (displayed text)
   */
  label: string;

  /**
   * Whether the option is disabled
   * @default false
   */
  disabled?: boolean;
}

/**
 * Option group for Select component
 */
export interface SelectOptionGroup {
  /**
   * Group label
   */
  label: string;

  /**
   * Options in the group
   */
  options: SelectOption[];
}

/**
 * Select component props
 */
export interface SelectProps extends Omit<SelectHTMLAttributes<HTMLSelectElement>, 'size'> {
  /**
   * Visual state of the select
   * @default 'default'
   */
  state?: 'default' | 'error' | 'success';

  /**
   * Size variant
   * @default 'md'
   */
  size?: 'sm' | 'md' | 'lg';

  /**
   * Whether select should take full width
   * @default true
   */
  fullWidth?: boolean;

  /**
   * Options (simple array)
   */
  options?: SelectOption[];

  /**
   * Grouped options
   */
  optionGroups?: SelectOptionGroup[];

  /**
   * Placeholder text (shown as first disabled option)
   */
  placeholder?: string;

  /**
   * Loading state (shows spinner, disables interaction)
   * @default false
   */
  loading?: boolean;
}

/**
 * Select ref type
 */
export type SelectRef = HTMLSelectElement;

