  approval,
  agentId,
  conversationId,
  onResolved,
}: ToolApprovalCardProps) {
  const [submitting, setSubmitting] = useState(false);

  const handleDecision = async (decision: 'approve' | 'deny') => {
    setSubmitting(true);
    try {
