'use client';

import type { AIProvider } from '@tpmjs/types/agent';
import { Badge } from '@tpmjs/ui/Badge/Badge';
import { Button } from '@tpmjs/ui/Button/Button';
import { Icon } from '@tpmjs/ui/Icon/Icon';
import { Textarea } from '@tpmjs/ui/Textarea/Textarea';
import Link from 'next/link';
import { useParams, useRouter } from 'next/navigation';
import { useCallback, useEffect, useRef, useState } from 'react';
import { Streamdown } from 'streamdown';
import type { AgentSettings } from '~/components/agents/ChatSettingsDrawer';
import { ChatSettingsDrawer } from '~/components/agents/ChatSettingsDrawer';
import type { CollectionInfo, ToolInfo } from '~/components/agents/ChatToolsPanel';
import { ChatToolsPanel } from '~/components/agents/ChatToolsPanel';
import { type PendingApproval, ToolApprovalCard } from '~/components/agents/ToolApprovalCard';
import { ToolDetailsModal } from '~/components/agents/ToolDetailsModal';
import { ConversationSandboxLogs } from '~/components/ConversationSandboxLogs';
import { DashboardLayout } from '~/components/dashboard/DashboardLayout';

interface Agent {
  id: string;
  uid: string;
  name: string;
  description: string | null;
  provider: AIProvider;
  modelId: string;
  systemPrompt: string | null;
  temperature: number;
  maxToolCallsPerTurn: number;
  maxMessagesInContext: number;
  sandboxEnabled: boolean;
  tools: ToolInfo[];
  collections: CollectionInfo[];
}

interface MessageToolCall {
  toolCallId: string;
  toolName: string;
  args?: Record<string, unknown>;
}

interface Message {
  id: string;
  role: 'USER' | 'ASSISTANT' | 'TOOL';
  content: string;
  toolName?: string;
  toolCallId?: string;
  toolResult?: unknown;
  toolCalls?: MessageToolCall[] | null;
  createdAt: string;
}

interface ToolCall {
  toolCallId: string;
  toolName: string;
  input?: unknown;
  output?: unknown;
  status: 'pending' | 'running' | 'success' | 'error';
}

/**
 * Check if a tool output contains an error
 */
function isToolError(output: unknown): boolean {
  if (!output || typeof output !== 'object') return false;
  const obj = output as Record<string, unknown>;
  return (
    obj.success === false ||
    obj.error !== undefined ||
    obj.__tpmjs_error__ !== undefined ||
    (typeof obj.message === 'string' && obj.message.toLowerCase().includes('error'))
  );
}

/**
 * Extract error message from tool output
 */
function getErrorMessage(output: unknown): string | null {
  if (!output || typeof output !== 'object') return null;
  const obj = output as Record<string, unknown>;
  if (typeof obj.error === 'string') return obj.error;
  if (typeof obj.__tpmjs_error__ === 'string') return obj.__tpmjs_error__;
  if (obj.success === false && typeof obj.message === 'string') return obj.message;
  return null;
}

/**
 * Tool call card with style guide aesthetics
 */
function ToolCallCard({
  toolCall,
  isExpanded,
  onToggle,
}: {
  toolCall: ToolCall;
  isExpanded: boolean;
  onToggle: () => void;
}) {
  const hasError = Boolean(toolCall.output && isToolError(toolCall.output));
  const errorMessage = hasError ? getErrorMessage(toolCall.output) : null;
  const effectiveStatus = hasError ? 'error' : toolCall.status;

  const statusColors = {
    pending: 'bg-warning/10 text-warning border-warning/30',
    running: 'bg-info/10 text-info border-info/30',
    success: 'bg-success/10 text-success border-success/30',
    error: 'bg-error/10 text-error border-error/30',
  };

  const statusIcons: Record<ToolCall['status'], 'loader' | 'check' | 'alertCircle' | 'info'> = {
    pending: 'info',
    running: 'loader',
    success: 'check',
    error: 'alertCircle',
  };

  const formatJson = (data: unknown): React.ReactNode => {
    try {
      return JSON.stringify(data, null, 2);
    } catch {
      return String(data);
    }
  };

  return (
    <fieldset
      className={`border border-dashed overflow-hidden font-mono text-xs ${
        hasError ? 'border-error/50 bg-error/5' : 'border-border bg-surface-secondary/30'
      }`}
    >
      {/* header */}
      <Button
        variant="ghost"
        onClick={onToggle}
        className="w-full flex items-center gap-3 p-3 h-auto justify-start rounded-none hover:bg-surface-secondary/80"
      >
        <div className={`p-1.5 rounded ${statusColors[effectiveStatus]}`}>
          <Icon
            icon={statusIcons[effectiveStatus]}
            size="xs"
            className={effectiveStatus === 'running' ? 'animate-spin' : ''}
          />
        </div>
        <div className="flex-1 text-left min-w-0">
          <div className="flex items-center gap-2">
            <span className="text-foreground font-semibold truncate">{toolCall.toolName}</span>
            <span className="text-foreground-tertiary text-[10px]">
              {toolCall.toolCallId.slice(0, 8)}...
            </span>
            {hasError && (
              <span className="text-[10px] px-1.5 py-0.5 rounded bg-error/10 text-error uppercase">
                error
              </span>
            )}
          </div>
          {hasError && errorMessage && !isExpanded && (
            <div className="text-error text-[10px] mt-1 truncate max-w-[300px]">{errorMessage}</div>
          )}
        </div>
        <Icon
          icon="chevronRight"
          size="xs"
          className={`text-foreground-tertiary transition-transform flex-shrink-0 ${isExpanded ? 'rotate-90' : ''}`}
        />
      </Button>

      {/* expanded content */}
      {isExpanded && (
        <div className="border-t border-dashed border-border">
          {/* input */}
          {toolCall.input !== undefined && toolCall.input !== null ? (
            <div className="p-3 border-b border-dashed border-border/50">
              <div className="flex items-center gap-2 mb-2">
                <span className="text-[10px] uppercase tracking-wider text-foreground-tertiary">
                  input
                </span>
                <div className="flex-1 h-px bg-border/50" />
              </div>
              <pre className="text-[11px] text-foreground-secondary overflow-x-auto whitespace-pre-wrap break-all max-h-48 overflow-y-auto">
                {formatJson(toolCall.input)}
              </pre>
            </div>
          ) : null}

          {/* error message */}
          {hasError && errorMessage && (
            <div className="p-3 bg-error/10 border-b border-dashed border-error/20">
              <div className="flex items-center gap-2 mb-2">
                <Icon icon="alertCircle" size="xs" className="text-error" />
                <span className="text-[10px] uppercase tracking-wider text-error font-semibold">
                  error
                </span>
              </div>
              <p className="text-[11px] text-error">{errorMessage}</p>
            </div>
          )}

          {/* output */}
          {toolCall.output !== undefined && toolCall.output !== null ? (
            <div className="p-3">
              <div className="flex items-center gap-2 mb-2">
                <span className="text-[10px] uppercase tracking-wider text-foreground-tertiary">
                  {hasError ? 'full response' : 'output'}
                </span>
                <div className="flex-1 h-px bg-border/50" />
              </div>
              <pre
                className={`text-[11px] overflow-x-auto whitespace-pre-wrap break-all max-h-48 overflow-y-auto ${hasError ? 'text-error' : 'text-success'}`}
              >
                {formatJson(toolCall.output)}
              </pre>
            </div>
          ) : null}

          {/* running indicator */}
          {toolCall.status === 'running' && !toolCall.output && (
            <div className="p-3 flex items-center gap-2 text-foreground-tertiary">
              <Icon icon="loader" size="xs" className="animate-spin" />
              <span>executing...</span>
            </div>
          )}
        </div>
      )}
    </fieldset>
  );
}

interface Conversation {
  id: string;
  slug: string;
  title: string | null;
  messageCount: number;
  updatedAt: string;
}

const PROVIDER_DISPLAY_NAMES: Record<AIProvider, string> = {
  OPENAI: 'OpenAI',
  ANTHROPIC: 'Anthropic',
  GOOGLE: 'Google',
  GROQ: 'Groq',
  MISTRAL: 'Mistral',
};

function generateConversationId(): string {
  return `conv-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
}

export default function AgentChatPage(): React.ReactElement {
  const params = useParams();
  const router = useRouter();
  const agentId = params.id as string;
  const chatId = params.chatId as string;

  const [agent, setAgent] = useState<Agent | null>(null);
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const activeConversationId = chatId;
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSending, setIsSending] = useState(false);
  const [streamingContent, setStreamingContent] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [errorDetails, setErrorDetails] = useState<Record<string, unknown> | null>(null);
  const [debugInfo, setDebugInfo] = useState<Record<string, unknown> | null>(null);
  const [warnings, setWarnings] = useState<string[]>([]);
  const [toolCalls, setToolCalls] = useState<ToolCall[]>([]);
  const [pendingApprovals, setPendingApprovals] = useState<PendingApproval[]>([]);
  const [expandedToolCalls, setExpandedToolCalls] = useState<Set<string>>(new Set());

  // UI state
  const [showToolsPanel, setShowToolsPanel] = useState(true);
  const [showSettings, setShowSettings] = useState(false);
  const [showSandboxLogs, setShowSandboxLogs] = useState(false);
  const [selectedTool, setSelectedTool] = useState<ToolInfo | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  const toggleToolCall = (toolCallId: string) => {
    setExpandedToolCalls((prev) => {
      const next = new Set(prev);
      if (next.has(toolCallId)) {
        next.delete(toolCallId);
      } else {
        next.add(toolCallId);
      }
      return next;
    });
  };

  // Fetch agent data
  const fetchAgent = useCallback(async () => {
    try {
      const response = await fetch(`/api/agents/${agentId}`);
      const data = await response.json();

      if (data.success) {
        setAgent(data.data);
      } else {
        if (response.status === 401) {
          router.push('/sign-in');
          return;
        }
        setError(data.error || 'Failed to fetch agent');
      }
    } catch (err) {
      console.error('Failed to fetch agent:', err);
      setError('Failed to fetch agent');
    }
  }, [agentId, router]);

  // Fetch conversations
  const fetchConversations = useCallback(async () => {
    if (!agent) return;

    try {
      const response = await fetch(`/api/agents/${agentId}/conversations`);
      const data = await response.json();

      if (data.success) {
        setConversations(data.data);
      }
    } catch (err) {
      console.error('Failed to fetch conversations:', err);
    }
  }, [agent, agentId]);

  // Fetch messages for active conversation
  const fetchMessages = useCallback(async () => {
    if (!agent || !activeConversationId) return;

    try {
      const response = await fetch(`/api/agents/${agentId}/conversation/${activeConversationId}`);
      const data = await response.json();

      if (data.success) {
        const msgs = data.data.messages || [];
        setMessages(msgs);
      }
    } catch (err) {
      console.error('Failed to fetch messages:', err);
    }
  }, [agent, agentId, activeConversationId]);

  useEffect(() => {
    const init = async () => {
      await fetchAgent();
      setIsLoading(false);
    };
    init();
  }, [fetchAgent]);

  useEffect(() => {
    if (agent) {
      fetchConversations();
    }
  }, [agent, fetchConversations]);

  useEffect(() => {
    if (activeConversationId) {
      fetchMessages();
    } else {
      setMessages([]);
    }
  }, [activeConversationId, fetchMessages]);

  // Scroll to bottom only when messages change or streaming content updates
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, []);

  const handleSelectConversation = (convSlug: string) => {
    router.push(`/dashboard/agents/${agentId}/chat/${convSlug}`);
  };

  const handleSend = async () => {
    if (!input.trim() || !agent || isSending) return;

    const messageContent = input.trim();
    setInput('');
    setIsSending(true);
    setStreamingContent('');
    setError(null);
    setErrorDetails(null);
    setDebugInfo(null);
    setWarnings([]);
    setToolCalls([]);

    const conversationId = activeConversationId || chatId;

    // Optimistically add user message
    const userMessage: Message = {
      id: `temp-${Date.now()}`,
      role: 'USER',
      content: messageContent,
      createdAt: new Date().toISOString(),
    };
    setMessages((prev) => [...prev, userMessage]);

    try {
      const response = await fetch(`/api/agents/${agentId}/conversation/${conversationId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: messageContent }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to send message');
      }

      // Handle SSE stream
      const reader = response.body?.getReader();
      if (!reader) throw new Error('No response body');

      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });

        // Parse SSE events
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';

        let eventType = '';
        for (const line of lines) {
          if (line.startsWith('event: ')) {
            eventType = line.slice(7);
          } else if (line.startsWith('data: ')) {
            const data = JSON.parse(line.slice(6));

            switch (eventType) {
              case 'debug':
                setDebugInfo(data);
                console.log('[Agent Chat] Stream debug:', data);
                break;
              case 'warning':
                setWarnings((prev) => [...prev, data.message]);
                console.warn('[Agent Chat] Stream warning:', data);
                break;
              case 'stream_error':
                // Actual provider error surfaced from the AI SDK fullStream
                console.error('[Agent Chat] Provider stream error:', data);
                setErrorDetails((prev) => ({ ...prev, streamError: data }));
                setWarnings((prev) => [...prev, `Provider error: ${data.message}`]);
                break;
              case 'chunk':
                setStreamingContent((prev) => prev + data.text);
                break;
              case 'tool_call':
                setToolCalls((prev) => [
                  ...prev,
                  {
                    toolCallId: data.toolCallId,
                    toolName: data.toolName,
                    input: data.input,
                    status: 'running',
                  },
                ]);
                setExpandedToolCalls((prev) => new Set([...prev, data.toolCallId]));
                break;
              case 'tool_result':
                setToolCalls((prev) =>
                  prev.map((tc) =>
                    tc.toolCallId === data.toolCallId
                      ? { ...tc, output: data.output, status: 'success' as const }
                      : tc
                  )
                );
                break;
              case 'approval_request':
                setPendingApprovals((prev) => [
                  ...prev,
                  {
                    approvalId: data.approvalId,
                    toolName: data.toolName,
                    input: data.input,
                    status: 'pending',
                  },
                ]);
                break;
              case 'approval_resolved':
                setPendingApprovals((prev) =>
                  prev.map((a) =>
                    a.approvalId === data.approvalId
                      ? { ...a, status: data.decision === 'approve' ? 'approved' : 'denied' }
                      : a
                  )
                );
                break;
              case 'approval_timeout':
                setPendingApprovals((prev) =>
                  prev.map((a) =>
                    a.approvalId === data.approvalId ? { ...a, status: 'timeout' } : a
                  )
                );
                break;
              case 'tools_loaded':
                console.log('[Agent Chat] Dynamic tools loaded:', data.tools);
                break;
              case 'complete':
                await fetchMessages();
                await fetchConversations();
                setStreamingContent('');
                setToolCalls([]);
                setPendingApprovals([]);
                break;
              case 'tokens':
                console.log('[Agent Chat] Token usage:', data);
                break;
              case 'error': {
                // Store structured error details for display
                const details = data.details || {};
                setErrorDetails(details);
                console.error('[Agent Chat] Stream error:', data);
                throw new Error(data.message);
              }
            }
          }
        }
      }
    } catch (err) {
      console.error('Failed to send message:', err);
      setError(err instanceof Error ? err.message : 'Failed to send message');
      setMessages((prev) => prev.filter((m) => m.id !== userMessage.id));
    } finally {
      setIsSending(false);
      setStreamingContent('');
      inputRef.current?.focus();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const startNewConversation = () => {
    const newId = generateConversationId();
    router.push(`/dashboard/agents/${agentId}/chat/${newId}`);
  };

  const handleSettingsChange = (newSettings: AgentSettings) => {
    if (agent) {
      setAgent({
        ...agent,
        ...newSettings,
      });
    }
  };

  if (isLoading) {
    return (
      <DashboardLayout
        title="Loading..."
        showBackButton
        backUrl={`/dashboard/agents/${agentId}`}
        fullHeight
      >
        <div className="flex items-center justify-center h-full">
          <Icon icon="loader" size="lg" className="animate-spin text-foreground-secondary" />
        </div>
      </DashboardLayout>
    );
  }

  if (error && !agent) {
    return (
      <DashboardLayout title="Error" showBackButton backUrl="/dashboard/agents" fullHeight>
        <div className="flex items-center justify-center h-full">
          <div className="text-center">
            <Icon icon="alertCircle" size="lg" className="mx-auto text-error mb-4" />
            <h2 className="text-lg font-medium text-foreground mb-2">Error</h2>
            <p className="text-foreground-secondary mb-4">{error}</p>
            <Link href="/dashboard/agents">
              <Button>Back to Agents</Button>
            </Link>
          </div>
        </div>
      </DashboardLayout>
    );
  }

  if (!agent) {
    return (
      <DashboardLayout
        title="Loading..."
        showBackButton
        backUrl={`/dashboard/agents/${agentId}`}
        fullHeight
      >
        <div className="flex items-center justify-center h-full">
          <Icon icon="loader" size="lg" className="animate-spin text-foreground-secondary" />
        </div>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout
      title={agent.name}
      subtitle={`${PROVIDER_DISPLAY_NAMES[agent.provider]} / ${agent.modelId}`}
      showBackButton
      backUrl={`/dashboard/agents/${agent.id}`}
      fullHeight
      actions={
        <div className="flex items-center gap-2">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setShowToolsPanel(!showToolsPanel)}
            title={showToolsPanel ? 'Hide tools panel' : 'Show tools panel'}
            className={showToolsPanel ? 'bg-primary/10 text-primary' : ''}
          >
            <Icon icon="puzzle" size="xs" className="mr-1.5" />
            <span className="hidden sm:inline">Tools</span>
            {agent.tools.length > 0 && (
              <Badge variant="secondary" className="ml-1.5 text-[10px]">
                {agent.tools.length}
              </Badge>
            )}
          </Button>
          {agent.sandboxEnabled && (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowSandboxLogs(!showSandboxLogs)}
              title={showSandboxLogs ? 'Hide sandbox logs' : 'Show sandbox logs'}
              className={showSandboxLogs ? 'bg-primary/10 text-primary' : ''}
            >
              <Icon icon="terminal" size="xs" className="mr-1.5" />
              <span className="hidden sm:inline">Sandbox</span>
            </Button>
          )}
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setShowSettings(true)}
            title="Agent settings"
          >
            <Icon icon="edit" size="xs" className="mr-1.5" />
            <span className="hidden sm:inline">Settings</span>
          </Button>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => {
              window.open(
                `/api/agents/${agentId}/conversation/${activeConversationId}?format=json`,
                '_blank'
              );
            }}
            title="View conversation as JSON"
          >
            <Icon icon="terminal" size="xs" />
          </Button>
          <Button variant="outline" size="sm" onClick={startNewConversation}>
            <Icon icon="plus" size="xs" className="mr-1.5" />
            New Chat
          </Button>
        </div>
      }
    >
      <div className="flex h-full overflow-hidden">
        {/* Conversations Sidebar */}
        <div className="w-56 border-r border-dashed border-border flex flex-col bg-surface hidden md:flex">
          <div className="p-3 border-b border-dashed border-border">
            <span className="font-mono text-xs text-foreground-tertiary lowercase">
              conversations
            </span>
          </div>
          <div className="flex-1 overflow-y-auto p-2">
            {conversations.length === 0 ? (
              <p className="text-xs text-foreground-tertiary text-center py-4 font-mono">
                no conversations yet
              </p>
            ) : (
              conversations.map((conv) => (
                <button
                  type="button"
                  key={conv.id}
                  onClick={() => handleSelectConversation(conv.slug)}
                  className={`w-full text-left p-2 mb-1 rounded border border-transparent transition-colors ${
                    chatId === conv.slug
                      ? 'bg-primary/10 border-primary/20 text-primary'
                      : 'text-foreground-secondary hover:bg-surface-secondary hover:border-border'
                  }`}
                >
                  <p className="text-sm font-medium truncate">{conv.title || 'Untitled Chat'}</p>
                  <p className="text-[10px] text-foreground-tertiary font-mono mt-0.5">
                    {conv.messageCount} messages
                  </p>
                </button>
              ))
            )}
          </div>
        </div>

        {/* Chat Area */}
        <div className="flex-1 flex flex-col min-w-0">
          {/* Messages */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4">
            {messages.length === 0 && !streamingContent && (
              <div className="flex items-center justify-center h-full">
                <fieldset className="border border-dashed border-border p-8 max-w-md text-center">
                  <legend className="px-2 font-mono text-xs text-foreground-tertiary lowercase">
                    new conversation
                  </legend>
                  <div className="w-14 h-14 rounded-full bg-primary/10 flex items-center justify-center mx-auto mb-4">
                    <Icon icon="message" size="lg" className="text-primary" />
                  </div>
                  <h3 className="font-mono text-foreground mb-2 lowercase">start chatting</h3>
                  <p className="text-sm text-foreground-secondary">
                    Send a message to start a conversation with {agent.name}.
                  </p>
                </fieldset>
              </div>
            )}

            {(() => {
              // Build a map of toolCallId -> tool result from TOOL messages
              const toolResultsMap = new Map<string, unknown>();
              for (const msg of messages) {
                if (msg.role === 'TOOL' && msg.toolCallId) {
                  let output: unknown;
                  if (msg.toolResult) {
                    output = msg.toolResult;
                  } else {
                    try {
                      output = JSON.parse(msg.content || '{}');
                    } catch {
                      output = { result: msg.content };
                    }
                  }
                  toolResultsMap.set(msg.toolCallId, output);
                }
              }

              return messages.map((message) => {
                const hasEmbeddedToolCalls =
                  message.role === 'ASSISTANT' &&
                  message.toolCalls &&
                  Array.isArray(message.toolCalls) &&
                  message.toolCalls.length > 0;

                return (
                  <div key={message.id} className="space-y-2">
                    {/* Render embedded tool calls from ASSISTANT messages */}
                    {hasEmbeddedToolCalls && (
                      <div className="space-y-2">
                        {message.toolCalls?.map((tc) => {
                          const toolOutput = toolResultsMap.get(tc.toolCallId);
                          const hasOutput = toolOutput !== undefined;

                          return (
                            <div key={tc.toolCallId} className="flex justify-start">
                              <div className="max-w-[85%]">
                                <ToolCallCard
                                  toolCall={{
                                    toolCallId: tc.toolCallId,
                                    toolName: tc.toolName,
                                    input: tc.args,
                                    output: toolOutput,
                                    status: hasOutput ? 'success' : 'pending',
                                  }}
                                  isExpanded={expandedToolCalls.has(tc.toolCallId)}
                                  onToggle={() => toggleToolCall(tc.toolCallId)}
                                />
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    )}

                    {/* Render the message content - skip TOOL messages */}
                    {message.role !== 'TOOL' && (
                      <div
                        className={`flex ${message.role === 'USER' ? 'justify-end' : 'justify-start'}`}
                      >
                        <div
                          className={`max-w-[85%] rounded-lg p-4 ${
                            message.role === 'USER'
                              ? 'bg-primary text-primary-foreground'
                              : 'bg-surface text-foreground border border-dashed border-border'
                          }`}
                        >
                          {message.role === 'USER' ? (
                            <div className="text-sm whitespace-pre-wrap">{message.content}</div>
                          ) : (
                            <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
                              <Streamdown>{message.content}</Streamdown>
                            </div>
                          )}
                        </div>
                      </div>
                    )}
                  </div>
                );
              });
            })()}

            {/* Live tool calls during streaming */}
            {toolCalls.length > 0 && (
              <div className="space-y-2">
                {toolCalls.map((tc) => (
                  <div key={tc.toolCallId} className="flex justify-start">
                    <div className="max-w-[85%]">
                      <ToolCallCard
                        toolCall={tc}
                        isExpanded={expandedToolCalls.has(tc.toolCallId)}
                        onToggle={() => toggleToolCall(tc.toolCallId)}
                      />
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* Pending approval cards */}
            {pendingApprovals.length > 0 && (
              <div className="space-y-2">
                {pendingApprovals.map((approval) => (
                  <div key={approval.approvalId} className="flex justify-start">
                    <div className="max-w-[85%]">
                      <ToolApprovalCard
                        approval={approval}
                        agentId={agent?.id || ''}
                        conversationId={chatId as string}
                        onResolved={(approvalId, decision) => {
                          setPendingApprovals((prev) =>
                            prev.map((a) =>
                              a.approvalId === approvalId
                                ? { ...a, status: decision === 'approve' ? 'approved' : 'denied' }
                                : a
                            )
                          );
                        }}
                      />
                    </div>
                  </div>
                ))}
              </div>
            )}

            {streamingContent && (
              <div className="flex justify-start">
                <div className="max-w-[85%] rounded-lg p-4 bg-surface border border-dashed border-border">
                  <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
                    <Streamdown>{streamingContent}</Streamdown>
                  </div>
                  <span className="inline-block w-2 h-4 bg-primary animate-pulse ml-1" />
                </div>
              </div>
            )}

            {isSending && !streamingContent && toolCalls.length === 0 && (
              <div className="flex justify-start">
                <div className="rounded-lg p-4 bg-surface border border-dashed border-border">
                  <div className="flex items-center gap-2 text-foreground-secondary">
                    <Icon icon="loader" size="sm" className="animate-spin" />
                    <span className="text-sm font-mono lowercase">thinking...</span>
                  </div>
                </div>
              </div>
            )}

            <div ref={messagesEndRef} />
          </div>

          {/* Warnings */}
          {warnings.length > 0 && (
            <div className="px-4 py-2 bg-warning/10 border-t border-dashed border-warning/20">
              {warnings.map((w, i) => (
                <p key={i} className="text-xs text-warning font-mono">
                  {w}
                </p>
              ))}
            </div>
          )}

          {/* Error Message with Debug Details */}
          {error && (
            <div className="px-4 py-3 bg-error/10 border-t border-dashed border-error/20 space-y-2">
              <div className="flex items-center gap-2">
                <Icon icon="alertCircle" size="xs" className="text-error flex-shrink-0" />
                <p className="text-sm text-error font-mono font-semibold">{error}</p>
              </div>
              {errorDetails && Object.keys(errorDetails).length > 0 && (
                <details className="text-xs font-mono">
                  <summary className="text-error/70 cursor-pointer hover:text-error">
                    debug details
                  </summary>
                  <pre className="mt-2 p-2 bg-error/5 rounded text-error/80 overflow-x-auto whitespace-pre-wrap break-all max-h-48 overflow-y-auto">
                    {JSON.stringify(errorDetails, null, 2)}
                  </pre>
                </details>
              )}
              {debugInfo && (
                <details className="text-xs font-mono">
                  <summary className="text-error/70 cursor-pointer hover:text-error">
                    stream config
                  </summary>
                  <pre className="mt-2 p-2 bg-error/5 rounded text-error/80 overflow-x-auto whitespace-pre-wrap break-all max-h-32 overflow-y-auto">
                    {JSON.stringify(debugInfo, null, 2)}
                  </pre>
                </details>
              )}
            </div>
          )}

          {/* Input Area */}
          <div className="border-t border-dashed border-border p-4 bg-surface">
            <div className="flex items-end gap-2">
              <Textarea
                ref={inputRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="Type a message..."
                rows={1}
                resize="none"
                className="flex-1 min-h-[48px] max-h-[200px] font-mono"
                style={{
                  height: 'auto',
                  minHeight: '48px',
                }}
                onInput={(e) => {
                  const target = e.target as HTMLTextAreaElement;
                  target.style.height = 'auto';
                  target.style.height = `${Math.min(target.scrollHeight, 200)}px`;
                }}
              />
              <Button onClick={handleSend} disabled={isSending || !input.trim()}>
                <Icon icon="send" size="sm" />
              </Button>
            </div>
            <p className="text-[10px] text-foreground-tertiary mt-2 font-mono">
              enter to send, shift+enter for new line
            </p>
          </div>
        </div>

        {/* Tools Panel */}
        <ChatToolsPanel
          tools={agent.tools}
          collections={agent.collections}
          isOpen={showToolsPanel}
          onClose={() => setShowToolsPanel(false)}
          onToolClick={setSelectedTool}
        />

        {/* Sandbox Logs Panel */}
        {agent.sandboxEnabled && (
          <ConversationSandboxLogs
            agentId={agentId}
            conversationSlug={chatId}
            isOpen={showSandboxLogs}
            onClose={() => setShowSandboxLogs(false)}
          />
        )}
      </div>

      {/* Tool Details Modal */}
      <ToolDetailsModal
        tool={selectedTool}
        open={!!selectedTool}
        onClose={() => setSelectedTool(null)}
      />

      {/* Settings Drawer */}
      <ChatSettingsDrawer
        open={showSettings}
        onClose={() => setShowSettings(false)}
        agentId={agent.id}
        settings={{
          name: agent.name,
          provider: agent.provider,
          modelId: agent.modelId,
          systemPrompt: agent.systemPrompt,
          temperature: agent.temperature,
          maxToolCallsPerTurn: agent.maxToolCallsPerTurn,
          maxMessagesInContext: agent.maxMessagesInContext,
        }}
        onSettingsChange={handleSettingsChange}
      />
    </DashboardLayout>
  );
}

/**
 * Agent Conversation Endpoint (Username/Slug-based version)
 *
 * POST: Send a message and stream the AI response
 * GET: Retrieve conversation history
 * DELETE: Delete a conversation
 *
 * This endpoint uses username and agent slug for public-friendly URLs.
 * Example: /api/ajax/agents/tpmjs-discord/conversation/my-conv-1
 *
 * Authentication: Supports both session auth and TPMJS API key auth.
 * Requires 'agent:chat' scope for API key access.
 */

import { randomUUID } from 'node:crypto';
import { Prisma, prisma } from '@tpmjs/db';
import type { AIProvider } from '@tpmjs/types/agent';
import { SendMessageSchema } from '@tpmjs/types/agent';
import type { LanguageModel, ModelMessage } from 'ai';
import { type NextRequest, NextResponse } from 'next/server';
import { decryptApiKey } from '@/lib/crypto/api-keys';
import { logActivity } from '~/lib/activity';
import { authenticateRequest, hasScope } from '~/lib/api-keys/middleware';
import { trackUsage } from '~/lib/api-keys/usage';
import { checkRateLimit, type RateLimitConfig } from '~/lib/rate-limit';
import { inferErrorCategory } from '~/lib/tracking/error-categories';
import { trackExecution } from '~/lib/tracking/executions';

/**
 * Rate limit for chat messages: 30 requests per minute
 * This is stricter than default because chat involves expensive LLM calls
 */
const CHAT_RATE_LIMIT: RateLimitConfig = {
  limit: 30,
  windowSeconds: 60,
};

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 300; // 5 minutes for long agentic runs

type RouteContext = {
  params: Promise<{ username: string; agentSlug: string; conversationId: string }>;
};

/**
 * Get AI provider SDK based on provider type
 */
async function getProviderModel(
  provider: AIProvider,
  modelId: string,
  apiKey: string
): Promise<LanguageModel> {
  switch (provider) {
    case 'OPENAI': {
      const { createOpenAI } = await import('@ai-sdk/openai');
      return createOpenAI({ apiKey })(modelId);
    }
    case 'ANTHROPIC': {
      const { createAnthropic } = await import('@ai-sdk/anthropic');
      return createAnthropic({ apiKey })(modelId);
    }
    case 'GOOGLE': {
      const { createGoogleGenerativeAI } = await import('@ai-sdk/google');
      return createGoogleGenerativeAI({ apiKey })(modelId);
    }
    case 'GROQ': {
      const { createGroq } = await import('@ai-sdk/groq');
      return createGroq({ apiKey })(modelId);
    }
    case 'MISTRAL': {
      const { createMistral } = await import('@ai-sdk/mistral');
      return createMistral({ apiKey })(modelId);
    }
    default:
      throw new Error(`Unsupported provider: ${provider}`);
  }
}

/**
 * POST /api/[username]/agents/[agentSlug]/conversation/[conversationId]
 * Send a message and stream the AI response via SSE
 */
// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic required
export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
  const startTime = Date.now();

  // Authenticate request (supports both session and API key)
  const authResult = await authenticateRequest();

  if (!authResult.authenticated) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  // Check scope for API key auth
  if (authResult.authenticated && !authResult.isSessionAuth) {
    if (!hasScope(authResult, 'agent:chat')) {
      return NextResponse.json(
        { error: 'API key does not have agent:chat scope' },
        { status: 403 }
      );
    }
  }

  // Check rate limit (after auth so we can track by user if needed)
  const rateLimitResponse = checkRateLimit(request, CHAT_RATE_LIMIT);
  if (rateLimitResponse) {
    return rateLimitResponse;
  }

  const { username, agentSlug, conversationId } = await context.params;

  try {
    const body = await request.json();
    const parsed = SendMessageSchema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json(
        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
        { status: 400 }
      );
    }

    // Fetch agent by username and slug with all tool relations
    const { fetchAgentByUsernameAndUidWithTools, buildAgentTools } = await import(
      '@/lib/agents/build-tools'
    );
    const agent = await fetchAgentByUsernameAndUidWithTools(username, agentSlug);

    if (!agent) {
      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
    }

    // Owner-only enforcement: Only the agent owner can chat with the agent
    if (authResult.userId !== agent.userId) {
      return NextResponse.json(
        {
          success: false,
          error:
            'Fork this agent to use it. Only the agent owner can chat with agents. ' +
            'Visit the agent page to fork it to your account.',
        },
        { status: 403 }
      );
    }

    // Map provider to expected key name format
    const providerKeyNames: Record<string, string> = {
      OPENAI: 'OPENAI_API_KEY',
      ANTHROPIC: 'ANTHROPIC_API_KEY',
      GOOGLE: 'GOOGLE_API_KEY',
      GROQ: 'GROQ_API_KEY',
      MISTRAL: 'MISTRAL_API_KEY',
    };
    const keyName = providerKeyNames[agent.provider];

    if (!keyName) {
      return NextResponse.json(
        { success: false, error: `Unsupported provider: ${agent.provider}` },
        { status: 400 }
      );
    }

    // Get user's API key for this provider
    const userApiKey = await prisma.userApiKey.findUnique({
      where: {
        userId_keyName: {
          userId: agent.userId,
          keyName,
        },
      },
    });

    if (!userApiKey) {
      return NextResponse.json(
        {
          success: false,
          error: `No API key configured for ${agent.provider}. Please add your API key in settings.`,
        },
        { status: 400 }
      );
    }

    // Decrypt the API key
    const apiKey = decryptApiKey(userApiKey.encryptedKey, userApiKey.keyIv);

    // Get or create conversation
    let conversation = await prisma.conversation.findUnique({
      where: {
        agentId_slug: {
          agentId: agent.id,
          slug: conversationId,
        },
      },
    });

    if (!conversation) {
      conversation = await prisma.conversation.create({
        data: {
          agentId: agent.id,
          slug: conversationId,
          title: parsed.data.message.slice(0, 100),
        },
      });

      // Log activity for new conversation (fire-and-forget)
      if (agent.userId) {
        logActivity({
          userId: agent.userId,
          type: 'AGENT_CONVERSATION_STARTED',
          targetName: agent.name,
          targetType: 'agent',
          agentId: agent.id,
        });
      }
    }

    // Fetch recent messages for context
    const recentMessages = await prisma.message.findMany({
      where: { conversationId: conversation.id },
      orderBy: { createdAt: 'desc' },
      take: agent.maxMessagesInContext,
    });

    // Reverse to get chronological order
    recentMessages.reverse();

    // Save user message
    await prisma.message.create({
      data: {
        conversationId: conversation.id,
        role: 'USER',
        content: parsed.data.message,
      },
    });

    // Build AI SDK messages from conversation history
    const { streamText, stepCountIs } = await import('ai');

    const messages: ModelMessage[] = [];

    // Add system prompt if defined
    if (agent.systemPrompt) {
      messages.push({
        role: 'system',
        content: agent.systemPrompt,
      });
    }

    // Build a set of tool call IDs that have corresponding tool results
    // This is needed because AI SDK requires every tool call to have a matching tool result
    const toolResultIds = new Set(
      recentMessages.filter((m) => m.role === 'TOOL' && m.toolCallId).map((m) => m.toolCallId)
    );

    // Add conversation history - properly format for AI SDK
    for (const msg of recentMessages) {
      if (msg.role === 'USER') {
        messages.push({ role: 'user', content: msg.content });
      } else if (msg.role === 'ASSISTANT') {
        // For assistant messages with tool calls, include ToolCallParts in content
        if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
          // Only include tool calls that have matching tool results
          // AI SDK fails if there's a tool call without a corresponding tool result
          const validToolCalls = (
            msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
          ).filter((tc) => toolResultIds.has(tc.toolCallId));

          if (validToolCalls.length > 0) {
            const toolCallParts = validToolCalls.map((tc) => ({
              type: 'tool-call' as const,
              toolCallId: tc.toolCallId,
              toolName: tc.toolName,
              input: tc.args,
            }));
            // Content includes text (if any) plus tool call parts
            const content: Array<
              | { type: 'text'; text: string }
              | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
            > = [];
            if (msg.content) {
              content.push({ type: 'text', text: msg.content });
            }
            content.push(...toolCallParts);
            messages.push({
              role: 'assistant',
              content,
            });
          } else {
            // All tool calls are missing results, just include text content
            messages.push({
              role: 'assistant',
              content: msg.content || '',
            });
          }
        } else {
          messages.push({
            role: 'assistant',
            content: msg.content,
          });
        }
      } else if (msg.role === 'TOOL') {
        // Tool results use the 'tool' role with content array
        messages.push({
          role: 'tool',
          content: [
            {
              type: 'tool-result' as const,
              toolCallId: msg.toolCallId || '',
              toolName: msg.toolName || '',
              output: {
                type: 'json' as const,
                value: msg.toolResult,
              },
            },
          ],
        });
      }
    }

    // Add new user message
    messages.push({ role: 'user', content: parsed.data.message });

    // Set up sandbox session if agent has sandbox enabled
    let sessionId: string | undefined;
    let _sandboxUrl: string | undefined;
    let _sandboxApiKey: string | undefined;
    if (agent.sandboxEnabled) {
      const { getSandboxConfig, createSandboxSession } = await import('@/lib/executors');
      const { url: sandboxUrl, apiKey: sandboxApiKey } = getSandboxConfig();
      if (!sandboxUrl) {
        return NextResponse.json(
          {
            success: false,
            error: 'Sandbox not available. AGENT_SANDBOX_URL is not configured.',
          },
          { status: 502 }
        );
      }
      _sandboxUrl = sandboxUrl;
      _sandboxApiKey = sandboxApiKey;
      sessionId = `${agent.id}:${conversationId}`;
      try {
        await createSandboxSession(sandboxUrl, sandboxApiKey, sessionId);
      } catch (error) {
        console.error('[Sandbox] Failed to create session:', error);
        return NextResponse.json(
          {
            success: false,
            error: `Failed to create sandbox session: ${error instanceof Error ? error.message : 'Unknown error'}`,
          },
          { status: 502 }
        );
      }
    }

    // Set up approval handler for tools with "ask" permission
    const { parseToolPermissions } = await import('@/lib/agents/permissions');
    const permissions = parseToolPermissions(agent.toolPermissions);
    const hasPendingApprovals = permissions !== null;
    let approvalSendEvent: ((event: string, data: unknown) => void) | null = null;

    // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: DB-polling approval flow with timeout logic
    async function handleToolApproval(toolName: string, input: unknown): Promise<boolean> {
      const toolCallId = randomUUID();
      const approval = await prisma.toolApproval.create({
        data: {
          conversationId: conversation.id,
          agentId: agent.id,
          toolCallId,
          toolName,
          inputArgs: input as object,
        },
      });
      if (approvalSendEvent) {
        approvalSendEvent('approval_request', { approvalId: approval.id, toolName, input });
      }
      const POLL_INTERVAL = 2000;
      const TIMEOUT = 120000;
      const start = Date.now();
      while (Date.now() - start < TIMEOUT) {
        await new Promise((r) => setTimeout(r, POLL_INTERVAL));
        const updated = await prisma.toolApproval.findUnique({
          where: { id: approval.id },
          select: { decision: true },
        });
        if (updated?.decision) {
          if (approvalSendEvent) {
            approvalSendEvent('approval_resolved', {
              approvalId: approval.id,
              decision: updated.decision,
            });
          }
          return updated.decision === 'approve';
        }
      }
      await prisma.toolApproval.update({
        where: { id: approval.id },
        data: { decision: 'deny', resolvedAt: new Date() },
      });
      if (approvalSendEvent) {
        approvalSendEvent('approval_timeout', { approvalId: approval.id, toolName });
      }
      return false;
    }
    const approvalHandler = hasPendingApprovals ? handleToolApproval : undefined;

    // Build tools from agent configuration
    const tools = buildAgentTools(
      agent,
      undefined,
      sessionId,
      _sandboxUrl,
      _sandboxApiKey,
      approvalHandler
    );
    const toolCount = Object.keys(tools).length;
    const toolNames = Object.keys(tools);

    console.log('[Agent] Built tools:', { toolCount, toolNames, agentId: agent.id });

    // Get the provider model
    const model = await getProviderModel(agent.provider, agent.modelId, apiKey);

    // Create SSE stream
    const stream = new ReadableStream({
      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic
      async start(controller) {
        const encoder = new TextEncoder();

        const sendEvent = (event: string, data: unknown) => {
          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
          controller.enqueue(encoder.encode(message));
        };

        // Bind approval SSE sender
        approvalSendEvent = sendEvent;

        // ML tracking: declared outside try so they're accessible in catch
        const sequenceId = randomUUID();
        const contextMessageCount = messages.length;
        const contextTokenCount = Math.round(
          messages.reduce((sum, m) => {
            const content = typeof m.content === 'string' ? m.content : JSON.stringify(m.content);
            return sum + content.length;
          }, 0) / 4
        );

        try {
          const startTime = Date.now();
          let fullContent = '';
          // Accumulate tool calls with their input args
          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
            new Map();
          // Collect tool results to save AFTER assistant message (for correct chronological order)
          const pendingToolResults: Array<{
            toolCallId: string;
            toolName: string;
            output: unknown;
          }> = [];
          let inputTokens = 0;
          let outputTokens = 0;
          const streamErrors: string[] = [];
          let turnIndex = 0;

          // Send debug info so the client knows the stream configuration
          sendEvent('debug', {
            provider: agent.provider,
            model: agent.modelId,
            toolCount,
            toolNames,
            messageCount: messages.length,
            sandboxEnabled: agent.sandboxEnabled,
          });

          // Stream the response with agentic loop control
          const result = await streamText({
            model,
            messages,
            tools,
            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
            onChunk: async ({ chunk }) => {
              // Stream tool calls as they come in and capture their inputs
              if (chunk.type === 'tool-call') {
                const input = 'args' in chunk ? chunk.args : chunk.input;

                // Log tool call for debugging
                console.log('[Agent] Tool call initiated:', {
                  toolName: chunk.toolName,
                  toolCallId: chunk.toolCallId,
                  input: JSON.stringify(input).slice(0, 500),
                });

                // Store tool call with input for later persistence
                toolCallsMap.set(chunk.toolCallId, {
                  toolCallId: chunk.toolCallId,
                  toolName: chunk.toolName,
                  args: input,
                });
                sendEvent('tool_call', {
                  toolCallId: chunk.toolCallId,
                  toolName: chunk.toolName,
                  input,
                });
              }
            },
            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex callback
            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
              // Capture tool calls from step finish (backup in case onChunk missed any)
              if (toolCalls && Array.isArray(toolCalls)) {
                for (const tc of toolCalls) {
                  if (!toolCallsMap.has(tc.toolCallId)) {
                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
                    const args =
                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
                    toolCallsMap.set(tc.toolCallId, {
                      toolCallId: tc.toolCallId,
                      toolName: tc.toolName,
                      args,
                    });
                  }
                }
              }

              // Send tool results via SSE but don't save yet (save after assistant message for correct order)
              if (toolResults && toolResults.length > 0) {
                for (const tr of toolResults) {
                  // Check if this is an error result (AI SDK wraps errors in the output)
                  const isError =
                    tr.output && typeof tr.output === 'object' && 'error' in tr.output;

                  // Log tool results for debugging
                  if (isError) {
                    console.error('[Agent] Tool execution failed:', {
                      toolName: tr.toolName,
                      toolCallId: tr.toolCallId,
                      error: tr.output,
                    });
                  } else {
                    console.log('[Agent] Tool execution success:', {
                      toolName: tr.toolName,
                      toolCallId: tr.toolCallId,
                      outputPreview: JSON.stringify(tr.output).slice(0, 200),
                    });
                  }

                  sendEvent('tool_result', {
                    toolCallId: tr.toolCallId,
                    output: tr.output,
                    isError,
                  });

                  // Collect tool results to save after assistant message
                  pendingToolResults.push({
                    toolCallId: tr.toolCallId,
                    toolName: tr.toolName,
                    output: tr.output,
                  });

                  // Track each tool call execution event with ML training fields
                  const toolCallArgs = toolCallsMap.get(tr.toolCallId)?.args;
                  trackExecution({
                    eventType: 'tool_call',
                    source: 'agent_chat',
                    userId: authResult.userId ?? undefined,
                    apiKeyId: authResult.apiKeyId ?? undefined,
                    agentId: agent.id,
                    toolName: tr.toolName,
                    status: isError ? 'error' : 'success',
                    errorMessage:
                      isError && tr.output && typeof tr.output === 'object' && 'error' in tr.output
                        ? String((tr.output as { error: unknown }).error)
                        : undefined,
                    // ML training data
                    sequenceId,
                    turnIndex: turnIndex++,
                    conversationId: conversation.id,
                    inputArgs: toolCallArgs,
                    outputSummary: tr.output,
                    availableToolCount: toolCount,
                    contextMessageCount,
                    contextTokenCount,
                  });
                }
              }

              // Track token usage
              if (usage) {
                inputTokens += usage.inputTokens ?? 0;
                outputTokens += usage.outputTokens ?? 0;
              }
            },
          });

          // Consume the full stream to catch errors that textStream silently swallows.
          // The AI SDK's textStream only yields text chunks and hides provider errors,
          // causing a generic "No output generated" when the actual error is e.g. a 401.
          for await (const part of result.fullStream) {
            if (part.type === 'text-delta') {
              fullContent += part.text;
              sendEvent('chunk', { type: 'text', text: part.text });
            } else if (part.type === 'error') {
              // This is the actual provider error (e.g. 401, 429, invalid model)
              const streamError = part.error;
              const errMsg =
                streamError instanceof Error ? streamError.message : String(streamError);
              streamErrors.push(errMsg);
              console.error('[Agent] Stream error part:', streamError);
              sendEvent('stream_error', {
                message: errMsg,
                raw: JSON.stringify(
                  streamError,
                  Object.getOwnPropertyNames(streamError || {})
                ).slice(0, 2000),
              });
            }
          }

          // Get final response data (may throw NoOutputGeneratedError if stream had 0 steps)
          let finalUsage: { inputTokens?: number; outputTokens?: number } | undefined;
          try {
            finalUsage = await result.usage;
          } catch (usageError) {
            // If usage rejects with NoOutputGeneratedError, the real error was already
            // captured via the fullStream 'error' part above. Log but don't re-throw.
            const cause =
              usageError instanceof Error ? (usageError as { cause?: unknown }).cause : undefined;
            const causeMsg =
              cause instanceof Error ? cause.message : cause ? String(cause) : undefined;
            if (causeMsg) streamErrors.push(causeMsg);
            console.warn('[Agent] Usage rejected (stream produced 0 steps):', {
              error: usageError instanceof Error ? usageError.message : String(usageError),
              cause: causeMsg,
            });
          }

          // Convert tool calls map to array for storage
          const allToolCalls = Array.from(toolCallsMap.values());

          // Update token counts from final usage
          if (finalUsage) {
            inputTokens = finalUsage.inputTokens ?? inputTokens;
            outputTokens = finalUsage.outputTokens ?? outputTokens;
          }

          // If there were stream errors and no content, save errors as the content
          const savedContent =
            fullContent ||
            (streamErrors.length > 0 ? `[Stream Error] ${streamErrors.join('\n')}` : '');

          // Save assistant message FIRST (so it has earlier createdAt than tool results)
          const assistantMessage = await prisma.message.create({
            data: {
              conversationId: conversation.id,
              role: 'ASSISTANT',
              content: savedContent,
              // Cast to Prisma-compatible JSON type
              toolCalls:
                allToolCalls.length > 0
                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
                  : Prisma.JsonNull,
              inputTokens,
              outputTokens,
              // ML training data
              availableToolCount: toolCount,
              availableToolNames: toolNames as unknown as Prisma.InputJsonValue,
              sequenceId,
              contextMessageCount,
              contextTokenCount,
            },
          });

          // Now save TOOL messages (after assistant, for correct chronological order)
          for (const tr of pendingToolResults) {
            await prisma.message.create({
              data: {
                conversationId: conversation.id,
                role: 'TOOL',
                content: JSON.stringify(tr.output),
                toolCallId: tr.toolCallId,
                toolName: tr.toolName,
                toolResult: tr.output as object,
              },
            });
          }

          // Update conversation timestamp
          await prisma.conversation.update({
            where: { id: conversation.id },
            data: { updatedAt: new Date() },
          });

          const executionTimeMs = Date.now() - startTime;

          // Send token usage
          sendEvent('tokens', {
            inputTokens,
            outputTokens,
            totalTokens: inputTokens + outputTokens,
          });

          // Warn if the response was completely empty (no text, no tool calls)
          if (!fullContent && allToolCalls.length === 0) {
            const streamErrorSummary =
              streamErrors.length > 0 ? `\nStream errors: ${streamErrors.join('; ')}` : '';
            console.warn('[Agent] Empty response from model:', {
              agentId: agent.id,
              provider: agent.provider,
              model: agent.modelId,
              toolCount,
              messageCount: messages.length,
              inputTokens,
              outputTokens,
              streamErrors,
            });
            sendEvent('warning', {
              type: 'empty_response',
              message: `Model returned no text and made no tool calls.${streamErrorSummary} Provider: ${agent.provider}, Model: ${agent.modelId}, Tools: ${toolCount}`,
              debug: {
                inputTokens,
                outputTokens,
                toolCount,
                provider: agent.provider,
                model: agent.modelId,
                streamErrors,
              },
            });
          }

          // Send completion event
          sendEvent('complete', {
            messageId: assistantMessage.id,
            conversationId: conversation.id,
            executionTimeMs,
            hasContent: !!fullContent,
            toolCallCount: allToolCalls.length,
          });

          // Track agent run execution event
          trackExecution({
            eventType: 'agent_run',
            source: 'agent_chat',
            userId: authResult.userId ?? undefined,
            apiKeyId: authResult.apiKeyId ?? undefined,
            agentId: agent.id,
            status: 'success',
            durationMs: executionTimeMs,
            tokensIn: inputTokens,
            tokensOut: outputTokens,
            // ML training data
            sequenceId,
            conversationId: conversation.id,
            availableToolCount: toolCount,
            contextMessageCount,
            contextTokenCount,
          });

          // Track usage
          if (authResult.userId) {
            trackUsage({
              apiKeyId: authResult.apiKeyId ?? undefined,
              userId: authResult.userId,
              endpoint: `/api/${username}/agents/${agentSlug}/conversation/${conversationId}`,
              method: 'POST',
              statusCode: 200,
              latencyMs: executionTimeMs,
              resourceType: 'agent',
              resourceId: agent.id,
              tokensIn: inputTokens,
              tokensOut: outputTokens,
              model: agent.modelId,
            });
          }
        } catch (error) {
          // Extract rich error details from provider SDK errors
          const errorMessage = error instanceof Error ? error.message : String(error);
          const errorStack = error instanceof Error ? error.stack : undefined;

          // In production, class names get minified (e.g. "aB" instead of "APICallError").
          // Try to infer the real error type from its properties.
          const err = error as Record<string, unknown>;
          const inferredType =
            err.statusCode || err.responseBody
              ? 'APICallError'
              : err.url && err.requestBodyValues
                ? 'APIRequestError'
                : error instanceof Error
                  ? error.constructor.name
                  : 'UnknownError';

          // AI SDK and provider errors often have additional properties
          const errorDetails: Record<string, unknown> = {
            type: inferredType,
            message: errorMessage,
            agentId: agent.id,
            provider: agent.provider,
            model: agent.modelId,
            toolCount,
          };

          // Extract HTTP status and response body from provider errors
          if (err.statusCode) errorDetails.statusCode = err.statusCode;
          if (err.status) errorDetails.status = err.status;
          if (err.responseBody) errorDetails.responseBody = String(err.responseBody).slice(0, 1000);
          if (err.url) errorDetails.url = err.url;
          if (err.requestBodyValues)
            errorDetails.requestBodyValues = JSON.stringify(err.requestBodyValues).slice(0, 500);
          if (err.cause) {
            const cause = err.cause as Record<string, unknown>;
            errorDetails.cause = cause.message || String(err.cause);
            if (cause.code) errorDetails.causeCode = cause.code;
          }
          if (err.data) errorDetails.data = err.data;
          if (err.responseHeaders)
            errorDetails.responseHeaders = JSON.stringify(err.responseHeaders).slice(0, 500);

          // Log full error for server debugging
          console.error('[Agent] Conversation stream error:', {
            error: errorMessage,
            stack: errorStack,
            ...errorDetails,
          });

          // Warn about orphaned sandbox session (TTL cleanup will handle it)
          if (sessionId && _sandboxUrl) {
            console.warn('[Sandbox] Stream error with active session — will expire via TTL:', {
              sessionId,
              sandboxUrl: _sandboxUrl,
            });
          }

          // Save error as an ASSISTANT message so it appears in conversation history and JSON export
          try {
            await prisma.message.create({
              data: {
                conversationId: conversation.id,
                role: 'ASSISTANT',
                content: `[Error] ${errorMessage}`,
                toolCalls: Prisma.JsonNull,
                inputTokens: 0,
                outputTokens: 0,
              },
            });
          } catch (saveErr) {
            console.error('[Agent] Failed to save error message:', saveErr);
          }

          // Send rich error event to client
          sendEvent('error', {
            message: errorMessage,
            type: inferredType,
            details: errorDetails,
          });

          // Track agent run error with ML training data
          const errMsg = error instanceof Error ? error.message : 'Unknown error';
          const errStatusCode = typeof err.statusCode === 'number' ? err.statusCode : undefined;
          trackExecution({
            eventType: 'agent_run',
            source: 'agent_chat',
            userId: authResult.userId ?? undefined,
            apiKeyId: authResult.apiKeyId ?? undefined,
            agentId: agent.id,
            status: 'error',
            durationMs: Date.now() - startTime,
            errorMessage: errMsg,
            errorCategory: inferErrorCategory({
              errorMessage: errMsg,
              statusCode: errStatusCode,
            }),
            // ML training data
            sequenceId,
            conversationId: conversation.id,
            availableToolCount: toolCount,
            contextMessageCount,
            contextTokenCount,
          });

          // Update conversation status to error
          prisma.conversation
            .update({
              where: { id: conversation.id },
              data: { status: 'error' },
            })
            .catch(() => {});

          // Track error
          if (authResult.userId) {
            trackUsage({
              apiKeyId: authResult.apiKeyId ?? undefined,
              userId: authResult.userId,
              endpoint: `/api/${username}/agents/${agentSlug}/conversation/${conversationId}`,
              method: 'POST',
              statusCode: 500,
              latencyMs: Date.now() - startTime,
              resourceType: 'agent',
              resourceId: agent.id,
              errorCode: 'STREAM_ERROR',
              errorMessage: error instanceof Error ? error.message : 'Unknown error',
            });
          }
        } finally {
          controller.close();
        }
      },
    });

    return new NextResponse(stream, {
      headers: {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        Connection: 'keep-alive',
      },
    });
  } catch (error) {
    console.error('Failed to process message:', error);
    return NextResponse.json(
      {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to process message',
      },
      { status: 500 }
    );
  }
}

/**
 * GET /api/[username]/agents/[agentSlug]/conversation/[conversationId]
 * Retrieve conversation history with pagination
 */
export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
  const { username, agentSlug, conversationId } = await context.params;
  const { searchParams } = new URL(request.url);

  const format = searchParams.get('format');
  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
  const before = searchParams.get('before');
  const after = searchParams.get('after');

  try {
    // Fetch agent by username and slug
    const agent = await prisma.agent.findFirst({
      where: {
        uid: agentSlug,
        user: { username },
      },
      select: {
        id: true,
        uid: true,
        name: true,
        provider: true,
        modelId: true,
        sandboxEnabled: true,
        executorType: true,
        executorConfig: true,
      },
    });

    if (!agent) {
      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
    }

    // Fetch conversation
    const conversation = await prisma.conversation.findUnique({
      where: {
        agentId_slug: {
          agentId: agent.id,
          slug: conversationId,
        },
      },
    });

    if (!conversation) {
      return NextResponse.json(
        { success: false, error: 'Conversation not found' },
        { status: 404 }
      );
    }

    // For JSON format, return all messages with full details
    if (format === 'json') {
      const allMessages = await prisma.message.findMany({
        where: { conversationId: conversation.id },
        orderBy: { createdAt: 'asc' },
      });

      const response = {
        _meta: {
          exportedAt: new Date().toISOString(),
          format: 'tpmjs-conversation-log',
          version: '1.0',
        },
        agent: {
          id: agent.id,
          uid: agent.uid,
          name: agent.name,
          provider: agent.provider,
          modelId: agent.modelId,
          executorType: agent.executorType,
          executorConfig: agent.executorConfig,
        },
        conversation: {
          id: conversation.id,
          slug: conversation.slug,
          title: conversation.title,
          status: conversation.status,
          createdAt: conversation.createdAt,
          updatedAt: conversation.updatedAt,
          messageCount: allMessages.length,
        },
        messages: allMessages.map((m) => ({
          id: m.id,
          role: m.role,
          content: m.content,
          toolCalls: m.toolCalls,
          toolCallId: m.toolCallId,
          toolName: m.toolName,
          toolResult: m.toolResult,
          inputTokens: m.inputTokens,
          outputTokens: m.outputTokens,
          // ML training fields
          availableToolCount: m.availableToolCount,
          availableToolNames: m.availableToolNames,
          sequenceId: m.sequenceId,
          contextMessageCount: m.contextMessageCount,
          contextTokenCount: m.contextTokenCount,
          createdAt: m.createdAt,
        })),
        stats: {
          totalMessages: allMessages.length,
          userMessages: allMessages.filter((m) => m.role === 'USER').length,
          assistantMessages: allMessages.filter((m) => m.role === 'ASSISTANT').length,
          toolResults: allMessages.filter((m) => m.role === 'TOOL').length,
          totalInputTokens: allMessages.reduce((sum, m) => sum + (m.inputTokens || 0), 0),
          totalOutputTokens: allMessages.reduce((sum, m) => sum + (m.outputTokens || 0), 0),
        },
      };

      // Return pretty-printed JSON with proper content type
      return new NextResponse(JSON.stringify(response, null, 2), {
        headers: {
          'Content-Type': 'application/json',
          'Content-Disposition': `inline; filename="${conversation.slug}-logs.json"`,
        },
      });
    }

    // Standard paginated response
    const whereClause: {
      conversationId: string;
      createdAt?: { lt?: Date; gt?: Date };
    } = { conversationId: conversation.id };

    if (before) {
      whereClause.createdAt = { lt: new Date(before) };
    } else if (after) {
      whereClause.createdAt = { gt: new Date(after) };
    }

    // Determine fetch order:
    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
    // - "after": Fetch asc (oldest first) to get messages after the cursor
    const shouldFetchDesc = !after;

    // Fetch messages
    const messages = await prisma.message.findMany({
      where: whereClause,
      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
      take: limit + 1,
    });

    const hasMore = messages.length > limit;
    let paginatedMessages = hasMore ? messages.slice(0, limit) : messages;

    // Reverse if we fetched in desc order to maintain chronological order
    if (shouldFetchDesc) {
      paginatedMessages = paginatedMessages.reverse();
    }

    const mappedMessages = paginatedMessages.map((m) => ({
      id: m.id,
      role: m.role,
      content: m.content,
      toolCalls: m.toolCalls,
      toolCallId: m.toolCallId,
      toolName: m.toolName,
      toolResult: m.toolResult,
      inputTokens: m.inputTokens,
      outputTokens: m.outputTokens,
      availableToolCount: m.availableToolCount,
      availableToolNames: m.availableToolNames,
      sequenceId: m.sequenceId,
      contextMessageCount: m.contextMessageCount,
      contextTokenCount: m.contextTokenCount,
      createdAt: m.createdAt,
    }));

    return NextResponse.json({
      success: true,
      data: {
        id: conversation.id,
        slug: conversation.slug,
        title: conversation.title,
        createdAt: conversation.createdAt,
        updatedAt: conversation.updatedAt,
        messages: mappedMessages,
      },
      pagination: {
        limit,
        hasMore,
        ...(before && { before }),
        ...(after && { after }),
      },
    });
  } catch (error) {
    console.error('Failed to fetch conversation:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to fetch conversation' },
      { status: 500 }
    );
  }
}

/**
 * DELETE /api/[username]/agents/[agentSlug]/conversation/[conversationId]
 * Delete a conversation
 */
export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
  const { username, agentSlug, conversationId } = await context.params;

  try {
    // Fetch agent by username and slug (include sandboxEnabled for cleanup)
    const agent = await prisma.agent.findFirst({
      where: {
        uid: agentSlug,
        user: { username },
      },
      select: { id: true, sandboxEnabled: true },
    });

    if (!agent) {
      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
    }

    // Destroy sandbox session if applicable (fire-and-forget)
    if (agent.sandboxEnabled) {
      const { getSandboxConfig, destroySandboxSession } = await import('@/lib/executors');
      const { url: sandboxUrl, apiKey: sandboxApiKey } = getSandboxConfig();
      if (sandboxUrl) {
        const sessionId = `${agent.id}:${conversationId}`;
        destroySandboxSession(sandboxUrl, sandboxApiKey, sessionId).catch(() => {});
      }
    }

    // Delete conversation (messages cascade)
    await prisma.conversation.deleteMany({
      where: {
        agentId: agent.id,
        slug: conversationId,
      },
    });

    return NextResponse.json({
      success: true,
      data: { deleted: true },
    });
  } catch (error) {
    console.error('Failed to delete conversation:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to delete conversation' },
      { status: 500 }
    );
  }
}

/**
 * Agent Conversation Endpoint (ID-based version)
 *
 * POST: Send a message and stream the AI response
 * GET: Retrieve conversation history
 * DELETE: Delete a conversation
 *
 * This endpoint uses agent id directly for dashboard usage.
 *
 * Authentication: Supports both session auth and TPMJS API key auth.
 * Requires 'agent:chat' scope for API key access.
 */

import { randomUUID } from 'node:crypto';
import { Prisma, prisma } from '@tpmjs/db';
import type { AIProvider } from '@tpmjs/types/agent';
import { SendMessageSchema } from '@tpmjs/types/agent';
import type { LanguageModel, ModelMessage } from 'ai';
import { type NextRequest, NextResponse } from 'next/server';
import { decryptApiKey } from '@/lib/crypto/api-keys';
import { logActivity } from '~/lib/activity';
import { authenticateRequest, hasScope } from '~/lib/api-keys/middleware';
import { trackUsage } from '~/lib/api-keys/usage';
import { checkRateLimit, type RateLimitConfig } from '~/lib/rate-limit';
import { inferErrorCategory } from '~/lib/tracking/error-categories';
import { trackExecution } from '~/lib/tracking/executions';

/**
 * Rate limit for chat messages: 30 requests per minute
 * This is stricter than default because chat involves expensive LLM calls
 */
const CHAT_RATE_LIMIT: RateLimitConfig = {
  limit: 30,
  windowSeconds: 60,
};

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 300; // 5 minutes for long agentic runs

type RouteContext = {
  params: Promise<{ id: string; conversationId: string }>;
};

/**
 * Get AI provider SDK based on provider type
 */
async function getProviderModel(
  provider: AIProvider,
  modelId: string,
  apiKey: string
): Promise<LanguageModel> {
  switch (provider) {
    case 'OPENAI': {
      const { createOpenAI } = await import('@ai-sdk/openai');
      return createOpenAI({ apiKey })(modelId);
    }
    case 'ANTHROPIC': {
      const { createAnthropic } = await import('@ai-sdk/anthropic');
      return createAnthropic({ apiKey })(modelId);
    }
    case 'GOOGLE': {
      const { createGoogleGenerativeAI } = await import('@ai-sdk/google');
      return createGoogleGenerativeAI({ apiKey })(modelId);
    }
    case 'GROQ': {
      const { createGroq } = await import('@ai-sdk/groq');
      return createGroq({ apiKey })(modelId);
    }
    case 'MISTRAL': {
      const { createMistral } = await import('@ai-sdk/mistral');
      return createMistral({ apiKey })(modelId);
    }
    default:
      throw new Error(`Unsupported provider: ${provider}`);
  }
}

/**
 * POST /api/agents/[id]/conversation/[conversationId]
 * Send a message and stream the AI response via SSE
 */
// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic required
export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
  const startTime = Date.now();

  // Authenticate request (supports both session and API key)
  const authResult = await authenticateRequest();

  if (!authResult.authenticated) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  // Check scope for API key auth
  if (authResult.authenticated && !authResult.isSessionAuth) {
    if (!hasScope(authResult, 'agent:chat')) {
      return NextResponse.json(
        { error: 'API key does not have agent:chat scope' },
        { status: 403 }
      );
    }
  }

  // Check rate limit (after auth so we can track by user if needed)
  const rateLimitResponse = checkRateLimit(request, CHAT_RATE_LIMIT);
  if (rateLimitResponse) {
    return rateLimitResponse;
  }

  const { id: agentId, conversationId } = await context.params;

  try {
    const body = await request.json();
    const parsed = SendMessageSchema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json(
        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
        { status: 400 }
      );
    }

    // Fetch agent with all tool relations using agent ID
    const { fetchAgentWithTools, buildAgentToolsWithDiscovery } = await import(
      '@/lib/agents/build-tools'
    );
    const { getRequiredEnvVarsForAgent, getMissingEnvVars } = await import(
      '@/lib/agents/env-helpers'
    );
    const agent = await fetchAgentWithTools(agentId);

    if (!agent) {
      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
    }

    // Check ownership
    const isOwner = authResult.userId === agent.userId;

    // Non-owners can only access PUBLIC agents
    if (!isOwner && !agent.isPublic) {
      // Don't reveal that the agent exists - return 404
      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
    }

    // Map provider to expected key name format
    const providerKeyNames: Record<string, string> = {
      OPENAI: 'OPENAI_API_KEY',
      ANTHROPIC: 'ANTHROPIC_API_KEY',
      GOOGLE: 'GOOGLE_API_KEY',
      GROQ: 'GROQ_API_KEY',
      MISTRAL: 'MISTRAL_API_KEY',
    };
    const keyName = providerKeyNames[agent.provider];

    if (!keyName) {
      return NextResponse.json(
        { success: false, error: `Unsupported provider: ${agent.provider}` },
        { status: 400 }
      );
    }

    let apiKey: string;
    let callerEnvVars: Record<string, string> | undefined;

    if (isOwner) {
      // Owner: use stored encrypted keys
      const userApiKey = await prisma.userApiKey.findUnique({
        where: {
          userId_keyName: {
            userId: agent.userId,
            keyName,
          },
        },
      });

      if (!userApiKey) {
        return NextResponse.json(
          {
            success: false,
            error: `No API key configured for ${agent.provider}. Please add your API key in settings.`,
          },
          { status: 400 }
        );
      }

      // Decrypt the API key
      apiKey = decryptApiKey(userApiKey.encryptedKey, userApiKey.keyIv);
      // callerEnvVars stays undefined - buildAgentTools will use agent's stored env vars
    } else {
      // Non-owner accessing public agent: must provide their own credentials
      if (!parsed.data.providerApiKey) {
        return NextResponse.json(
          {
            success: false,
            error: 'Public agent access requires your own API key',
            details: {
              code: 'MISSING_PROVIDER_KEY',
              requiredProvider: agent.provider,
              hint: `Provide your ${agent.provider} API key in the 'providerApiKey' field`,
            },
          },
          { status: 400 }
        );
      }

      apiKey = parsed.data.providerApiKey;
      callerEnvVars = parsed.data.env || {};

      // Check for required environment variables
      const requiredEnvVars = getRequiredEnvVarsForAgent(agent);
      const missingEnvVars = getMissingEnvVars(requiredEnvVars, callerEnvVars);

      if (missingEnvVars.length > 0) {
        return NextResponse.json(
          {
            success: false,
            error: 'Missing required environment variables',
            details: {
              code: 'MISSING_ENV_VARS',
              missingVars: missingEnvVars.map((e) => ({
                name: e.name,
                description: e.description,
              })),
              hint: "Provide these variables in the 'env' field of your request",
            },
          },
          { status: 400 }
        );
      }
    }

    // Get or create conversation
    let conversation = await prisma.conversation.findUnique({
      where: {
        agentId_slug: {
          agentId: agent.id,
          slug: conversationId,
        },
      },
    });

    if (!conversation) {
      conversation = await prisma.conversation.create({
        data: {
          agentId: agent.id,
          slug: conversationId,
          title: parsed.data.message.slice(0, 100),
        },
      });

      // Log activity for new conversation (fire-and-forget)
      if (agent.userId) {
        logActivity({
          userId: agent.userId,
          type: 'AGENT_CONVERSATION_STARTED',
          targetName: agent.name,
          targetType: 'agent',
          agentId: agent.id,
        });
      }
    }

    // Fetch recent messages for context
    const recentMessages = await prisma.message.findMany({
      where: { conversationId: conversation.id },
      orderBy: { createdAt: 'desc' },
      take: agent.maxMessagesInContext,
    });

    // Reverse to get chronological order
    recentMessages.reverse();

    // Save user message
    await prisma.message.create({
      data: {
        conversationId: conversation.id,
        role: 'USER',
        content: parsed.data.message,
      },
    });

    // Build AI SDK messages from conversation history
    const { streamText, stepCountIs } = await import('ai');

    const messages: ModelMessage[] = [];

    // Add system prompt if defined
    if (agent.systemPrompt) {
      messages.push({
        role: 'system',
        content: agent.systemPrompt,
      });
    }

    // Build a set of tool call IDs that have corresponding tool results
    // This is needed because AI SDK requires every tool call to have a matching tool result
    const toolResultIds = new Set(
      recentMessages.filter((m) => m.role === 'TOOL' && m.toolCallId).map((m) => m.toolCallId)
    );

    // Add conversation history - properly format for AI SDK
    for (const msg of recentMessages) {
      if (msg.role === 'USER') {
        messages.push({ role: 'user', content: msg.content });
      } else if (msg.role === 'ASSISTANT') {
        // For assistant messages with tool calls, include ToolCallParts in content
        if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
          // Only include tool calls that have matching tool results
          // AI SDK fails if there's a tool call without a corresponding tool result
          const validToolCalls = (
            msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
          ).filter((tc) => toolResultIds.has(tc.toolCallId));

          if (validToolCalls.length > 0) {
            const toolCallParts = validToolCalls.map((tc) => ({
              type: 'tool-call' as const,
              toolCallId: tc.toolCallId,
              toolName: tc.toolName,
              input: tc.args,
            }));
            // Content includes text (if any) plus tool call parts
            const content: Array<
              | { type: 'text'; text: string }
              | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
            > = [];
            if (msg.content) {
              content.push({ type: 'text', text: msg.content });
            }
            content.push(...toolCallParts);
            messages.push({
              role: 'assistant',
              content,
            });
          } else {
            // All tool calls are missing results, just include text content
            messages.push({
              role: 'assistant',
              content: msg.content || '',
            });
          }
        } else {
          messages.push({
            role: 'assistant',
            content: msg.content,
          });
        }
      } else if (msg.role === 'TOOL') {
        // Tool results use the 'tool' role with content array
        messages.push({
          role: 'tool',
          content: [
            {
              type: 'tool-result' as const,
              toolCallId: msg.toolCallId || '',
              toolName: msg.toolName || '',
              output: {
                type: 'json' as const,
                value: msg.toolResult,
              },
            },
          ],
        });
      }
    }

    // Add new user message
    messages.push({ role: 'user', content: parsed.data.message });

    // Set up sandbox session if agent has sandbox enabled
    let sessionId: string | undefined;
    let _sandboxUrl: string | undefined;
    let _sandboxApiKey: string | undefined;
    if (agent.sandboxEnabled) {
      const { getSandboxConfig, createSandboxSession } = await import('@/lib/executors');
      const { url: sandboxUrl, apiKey: sandboxApiKey } = getSandboxConfig();
      if (!sandboxUrl) {
        return NextResponse.json(
          {
            success: false,
            error: 'Sandbox not available. AGENT_SANDBOX_URL is not configured.',
          },
          { status: 502 }
        );
      }
      _sandboxUrl = sandboxUrl;
      _sandboxApiKey = sandboxApiKey;
      sessionId = `${agent.id}:${conversationId}`;
      try {
        await createSandboxSession(sandboxUrl, sandboxApiKey, sessionId);
      } catch (error) {
        console.error('[Sandbox] Failed to create session:', error);
        return NextResponse.json(
          {
            success: false,
            error: `Failed to create sandbox session: ${error instanceof Error ? error.message : 'Unknown error'}`,
          },
          { status: 502 }
        );
      }
    }

    // Set up approval handler for tools with "ask" permission
    // The handler creates a ToolApproval row and polls DB until user responds
    const { parseToolPermissions } = await import('@/lib/agents/permissions');
    const permissions = parseToolPermissions(agent.toolPermissions);
    const hasPendingApprovals = permissions !== null;

    // approvalSendEvent will be bound once the SSE stream starts
    let approvalSendEvent: ((event: string, data: unknown) => void) | null = null;

    // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: DB-polling approval flow with timeout logic
    async function handleToolApproval(toolName: string, input: unknown): Promise<boolean> {
      const toolCallId = randomUUID();
      // Insert pending approval
      const approval = await prisma.toolApproval.create({
        data: {
          conversationId: conversation.id,
          agentId: agent.id,
          toolCallId,
          toolName,
          inputArgs: input as object,
        },
      });

      // Send approval request via SSE
      if (approvalSendEvent) {
        approvalSendEvent('approval_request', {
          approvalId: approval.id,
          toolName,
          input,
        });
      }

      // Poll DB for decision (2s interval, 120s timeout)
      const POLL_INTERVAL = 2000;
      const TIMEOUT = 120000;
      const start = Date.now();

      while (Date.now() - start < TIMEOUT) {
        await new Promise((r) => setTimeout(r, POLL_INTERVAL));
        const updated = await prisma.toolApproval.findUnique({
          where: { id: approval.id },
          select: { decision: true },
        });

        if (updated?.decision) {
          if (approvalSendEvent) {
            approvalSendEvent('approval_resolved', {
              approvalId: approval.id,
              decision: updated.decision,
            });
          }
          return updated.decision === 'approve';
        }
      }

      // Timeout: auto-deny
      await prisma.toolApproval.update({
        where: { id: approval.id },
        data: { decision: 'deny', resolvedAt: new Date() },
      });
      if (approvalSendEvent) {
        approvalSendEvent('approval_timeout', {
          approvalId: approval.id,
          toolName,
        });
      }
      return false;
    }
    const approvalHandler = hasPendingApprovals ? handleToolApproval : undefined;

    // Build tools from agent configuration (supports dynamic discovery)
    const { createToolDefinition } = await import('@/lib/ai-agent/tool-executor-agent');
    const { parseExecutorConfig } = await import('@/lib/executors');

    const { tools, allToolPool, isDynamic } = buildAgentToolsWithDiscovery(
      agent,
      callerEnvVars,
      sessionId,
      _sandboxUrl,
      _sandboxApiKey,
      approvalHandler
    );
    const toolCount = Object.keys(tools).length;
    const toolNames = Object.keys(tools);

    console.log('[Agent] Built tools:', { toolCount, toolNames, agentId: agent.id });

    // Get the provider model
    const model = await getProviderModel(agent.provider, agent.modelId, apiKey);

    // Create SSE stream
    const stream = new ReadableStream({
      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic
      async start(controller) {
        const encoder = new TextEncoder();

        const sendEvent = (event: string, data: unknown) => {
          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
          controller.enqueue(encoder.encode(message));
        };

        // Bind the approval SSE sender so the approval handler can send events
        approvalSendEvent = sendEvent;

        // ML tracking: declared outside try so they're accessible in catch
        const sequenceId = randomUUID();
        const contextMessageCount = messages.length;
        const contextTokenCount = Math.round(
          messages.reduce((sum, m) => {
            const content = typeof m.content === 'string' ? m.content : JSON.stringify(m.content);
            return sum + content.length;
          }, 0) / 4
        );

        try {
          const startTime = Date.now();
          let fullContent = '';
          // Accumulate tool calls with their input args
          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
            new Map();
          // Collect tool results to save AFTER assistant message (for correct chronological order)
          const pendingToolResults: Array<{
            toolCallId: string;
            toolName: string;
            output: unknown;
          }> = [];
          let inputTokens = 0;
          let outputTokens = 0;
          const streamErrors: string[] = [];
          let turnIndex = 0;

          // Send debug info so the client knows the stream configuration
          sendEvent('debug', {
            provider: agent.provider,
            model: agent.modelId,
            toolCount,
            toolNames,
            messageCount: messages.length,
            sandboxEnabled: agent.sandboxEnabled,
          });

          // Stream the response with agentic loop control
          const result = await streamText({
            model,
            messages,
            tools,
            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
            onChunk: async ({ chunk }) => {
              // Stream tool calls as they come in and capture their inputs
              if (chunk.type === 'tool-call') {
                const input = 'args' in chunk ? chunk.args : chunk.input;

                // Log tool call for debugging
                console.log('[Agent] Tool call initiated:', {
                  toolName: chunk.toolName,
                  toolCallId: chunk.toolCallId,
                  input: JSON.stringify(input).slice(0, 500),
                });

                // Store tool call with input for later persistence
                toolCallsMap.set(chunk.toolCallId, {
                  toolCallId: chunk.toolCallId,
                  toolName: chunk.toolName,
                  args: input,
                });
                sendEvent('tool_call', {
                  toolCallId: chunk.toolCallId,
                  toolName: chunk.toolName,
                  input,
                });
              }
            },
            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex callback
            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
              // Capture tool calls from step finish (backup in case onChunk missed any)
              if (toolCalls && Array.isArray(toolCalls)) {
                for (const tc of toolCalls) {
                  if (!toolCallsMap.has(tc.toolCallId)) {
                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
                    const args =
                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
                    toolCallsMap.set(tc.toolCallId, {
                      toolCallId: tc.toolCallId,
                      toolName: tc.toolName,
                      args,
                    });
                  }
                }
              }

              // Send tool results via SSE but don't save yet (save after assistant message for correct order)
              if (toolResults && toolResults.length > 0) {
                for (const tr of toolResults) {
                  // Check if this is an error result (AI SDK wraps errors in the output)
                  const isError =
                    tr.output && typeof tr.output === 'object' && 'error' in tr.output;

                  // Log tool results for debugging
                  if (isError) {
                    console.error('[Agent] Tool execution failed:', {
                      toolName: tr.toolName,
                      toolCallId: tr.toolCallId,
                      error: tr.output,
                    });
                  } else {
                    console.log('[Agent] Tool execution success:', {
                      toolName: tr.toolName,
                      toolCallId: tr.toolCallId,
                      outputPreview: JSON.stringify(tr.output).slice(0, 200),
                    });
                  }

                  sendEvent('tool_result', {
                    toolCallId: tr.toolCallId,
                    output: tr.output,
                    isError,
                  });

                  // Collect tool results to save after assistant message
                  pendingToolResults.push({
                    toolCallId: tr.toolCallId,
                    toolName: tr.toolName,
                    output: tr.output,
                  });

                  // Track each tool call execution event with ML training fields
                  const toolCallArgs = toolCallsMap.get(tr.toolCallId)?.args;
                  trackExecution({
                    eventType: 'tool_call',
                    source: 'agent_chat',
                    userId: authResult.userId ?? undefined,
                    apiKeyId: authResult.apiKeyId ?? undefined,
                    agentId: agent.id,
                    toolName: tr.toolName,
                    status: isError ? 'error' : 'success',
                    errorMessage:
                      isError && tr.output && typeof tr.output === 'object' && 'error' in tr.output
                        ? String((tr.output as { error: unknown }).error)
                        : undefined,
                    // ML training data
                    sequenceId,
                    turnIndex: turnIndex++,
                    conversationId: conversation.id,
                    inputArgs: toolCallArgs,
                    outputSummary: tr.output,
                    availableToolCount: toolCount,
                    contextMessageCount,
                    contextTokenCount,
                  });
                }
              }

              // Dynamic tool discovery: inject tools found by searchTools
              if (isDynamic && toolResults) {
                for (const tr of toolResults) {
                  if (tr.toolName === 'searchTools' && tr.output && typeof tr.output === 'object') {
                    const output = tr.output as { results?: Array<{ name: string }> };
                    if (output.results) {
                      const newlyLoaded: string[] = [];
                      const agentExecutorConfig = parseExecutorConfig(
                        agent.executorType,
                        agent.executorConfig
                      );
                      const individualConfig = agentExecutorConfig ?? { type: 'default' as const };
                      const useCallerEnv = callerEnvVars !== undefined;
                      const agentEnv = useCallerEnv
                        ? callerEnvVars
                        : (agent.envVars as Record<string, string>) || {};

                      for (const match of output.results) {
                        if (!tools[match.name]) {
                          const poolEntry = allToolPool.find((p) => p.name === match.name);
                          if (poolEntry) {
                            tools[match.name] = createToolDefinition(
                              poolEntry.tool,
                              individualConfig,
                              agentEnv
                            );
                            newlyLoaded.push(match.name);
                          }
                        }
                      }
                      if (newlyLoaded.length > 0) {
                        sendEvent('tools_loaded', { tools: newlyLoaded });
                      }
                    }
                  }
                }
              }

              // Track token usage
              if (usage) {
                inputTokens += usage.inputTokens ?? 0;
                outputTokens += usage.outputTokens ?? 0;
              }
            },
          });

          // Consume the full stream to catch errors that textStream silently swallows.
          // The AI SDK's textStream only yields text chunks and hides provider errors,
          // causing a generic "No output generated" when the actual error is e.g. a 401.
          for await (const part of result.fullStream) {
            if (part.type === 'text-delta') {
              fullContent += part.text;
              sendEvent('chunk', { type: 'text', text: part.text });
            } else if (part.type === 'error') {
              // This is the actual provider error (e.g. 401, 429, invalid model)
              const streamError = part.error;
              const errMsg =
                streamError instanceof Error ? streamError.message : String(streamError);
              streamErrors.push(errMsg);
              console.error('[Agent] Stream error part:', streamError);
              sendEvent('stream_error', {
                message: errMsg,
                raw: JSON.stringify(
                  streamError,
                  Object.getOwnPropertyNames(streamError || {})
                ).slice(0, 2000),
              });
            }
          }

          // Get final response data (may throw NoOutputGeneratedError if stream had 0 steps)
          let finalUsage: { inputTokens?: number; outputTokens?: number } | undefined;
          try {
            finalUsage = await result.usage;
          } catch (usageError) {
            // If usage rejects with NoOutputGeneratedError, the real error was already
            // captured via the fullStream 'error' part above. Log but don't re-throw.
            const cause =
              usageError instanceof Error ? (usageError as { cause?: unknown }).cause : undefined;
            const causeMsg =
              cause instanceof Error ? cause.message : cause ? String(cause) : undefined;
            if (causeMsg) streamErrors.push(causeMsg);
            console.warn('[Agent] Usage rejected (stream produced 0 steps):', {
              error: usageError instanceof Error ? usageError.message : String(usageError),
              cause: causeMsg,
            });
          }

          // Convert tool calls map to array for storage
          const allToolCalls = Array.from(toolCallsMap.values());

          // Update token counts from final usage
          if (finalUsage) {
            inputTokens = finalUsage.inputTokens ?? inputTokens;
            outputTokens = finalUsage.outputTokens ?? outputTokens;
          }

          // If there were stream errors and no content, save errors as the content
          const savedContent =
            fullContent ||
            (streamErrors.length > 0 ? `[Stream Error] ${streamErrors.join('\n')}` : '');

          // Save assistant message FIRST (so it has earlier createdAt than tool results)
          const assistantMessage = await prisma.message.create({
            data: {
              conversationId: conversation.id,
              role: 'ASSISTANT',
              content: savedContent,
              // Cast to Prisma-compatible JSON type
              toolCalls:
                allToolCalls.length > 0
                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
                  : Prisma.JsonNull,
              inputTokens,
              outputTokens,
              // ML training data
              availableToolCount: toolCount,
              availableToolNames: toolNames as unknown as Prisma.InputJsonValue,
              sequenceId,
              contextMessageCount,
              contextTokenCount,
            },
          });

          // Now save TOOL messages (after assistant, for correct chronological order)
          for (const tr of pendingToolResults) {
            await prisma.message.create({
              data: {
                conversationId: conversation.id,
                role: 'TOOL',
                content: JSON.stringify(tr.output),
                toolCallId: tr.toolCallId,
                toolName: tr.toolName,
                toolResult: tr.output as object,
              },
            });
          }

          // Update conversation timestamp
          await prisma.conversation.update({
            where: { id: conversation.id },
            data: { updatedAt: new Date() },
          });

          const executionTimeMs = Date.now() - startTime;

          // Send token usage
          sendEvent('tokens', {
            inputTokens,
            outputTokens,
            totalTokens: inputTokens + outputTokens,
          });

          // Warn if the response was completely empty (no text, no tool calls)
          if (!fullContent && allToolCalls.length === 0) {
            const streamErrorSummary =
              streamErrors.length > 0 ? `\nStream errors: ${streamErrors.join('; ')}` : '';
            console.warn('[Agent] Empty response from model:', {
              agentId: agent.id,
              provider: agent.provider,
              model: agent.modelId,
              toolCount,
              messageCount: messages.length,
              inputTokens,
              outputTokens,
              streamErrors,
            });
            sendEvent('warning', {
              type: 'empty_response',
              message: `Model returned no text and made no tool calls.${streamErrorSummary} Provider: ${agent.provider}, Model: ${agent.modelId}, Tools: ${toolCount}`,
              debug: {
                inputTokens,
                outputTokens,
                toolCount,
                provider: agent.provider,
                model: agent.modelId,
                streamErrors,
              },
            });
          }

          // Send completion event
          sendEvent('complete', {
            messageId: assistantMessage.id,
            conversationId: conversation.id,
            executionTimeMs,
            hasContent: !!fullContent,
            toolCallCount: allToolCalls.length,
          });

          // Track agent run execution event
          trackExecution({
            eventType: 'agent_run',
            source: 'agent_chat',
            userId: authResult.userId ?? undefined,
            apiKeyId: authResult.apiKeyId ?? undefined,
            agentId: agent.id,
            status: 'success',
            durationMs: executionTimeMs,
            tokensIn: inputTokens,
            tokensOut: outputTokens,
            // ML training data
            sequenceId,
            conversationId: conversation.id,
            availableToolCount: toolCount,
            contextMessageCount,
            contextTokenCount,
          });

          // Track usage
          if (authResult.userId) {
            trackUsage({
              apiKeyId: authResult.apiKeyId ?? undefined,
              userId: authResult.userId,
              endpoint: `/api/agents/${agentId}/conversation/${conversationId}`,
              method: 'POST',
              statusCode: 200,
              latencyMs: executionTimeMs,
              resourceType: 'agent',
              resourceId: agentId,
              tokensIn: inputTokens,
              tokensOut: outputTokens,
              model: agent.modelId,
            });
          }
        } catch (error) {
          // Extract rich error details from provider SDK errors
          const errorMessage = error instanceof Error ? error.message : String(error);
          const errorStack = error instanceof Error ? error.stack : undefined;

          // In production, class names get minified (e.g. "aB" instead of "APICallError").
          // Try to infer the real error type from its properties.
          const err = error as Record<string, unknown>;
          const inferredType =
            err.statusCode || err.responseBody
              ? 'APICallError'
              : err.url && err.requestBodyValues
                ? 'APIRequestError'
                : error instanceof Error
                  ? error.constructor.name
                  : 'UnknownError';

          // AI SDK and provider errors often have additional properties
          const errorDetails: Record<string, unknown> = {
            type: inferredType,
            message: errorMessage,
            agentId: agent.id,
            provider: agent.provider,
            model: agent.modelId,
            toolCount,
          };

          // Extract HTTP status and response body from provider errors
          // @ai-sdk/openai errors have statusCode, responseBody, etc.
          if (err.statusCode) errorDetails.statusCode = err.statusCode;
          if (err.status) errorDetails.status = err.status;
          if (err.responseBody) errorDetails.responseBody = String(err.responseBody).slice(0, 1000);
          if (err.url) errorDetails.url = err.url;
          if (err.requestBodyValues)
            errorDetails.requestBodyValues = JSON.stringify(err.requestBodyValues).slice(0, 500);
          if (err.cause) {
            const cause = err.cause as Record<string, unknown>;
            errorDetails.cause = cause.message || String(err.cause);
            if (cause.code) errorDetails.causeCode = cause.code;
          }
          if (err.data) errorDetails.data = err.data;
          if (err.responseHeaders)
            errorDetails.responseHeaders = JSON.stringify(err.responseHeaders).slice(0, 500);

          // Log full error for server debugging
          console.error('[Agent] Conversation stream error:', {
            error: errorMessage,
            stack: errorStack,
            ...errorDetails,
          });

          // Save error as an ASSISTANT message so it appears in conversation history and JSON export
          try {
            await prisma.message.create({
              data: {
                conversationId: conversation.id,
                role: 'ASSISTANT',
                content: `[Error] ${errorMessage}`,
                toolCalls: Prisma.JsonNull,
                inputTokens: 0,
                outputTokens: 0,
              },
            });
          } catch (saveErr) {
            console.error('[Agent] Failed to save error message:', saveErr);
          }

          // Send rich error event to client
          sendEvent('error', {
            message: errorMessage,
            type: inferredType,
            details: errorDetails,
          });

          // Track agent run error with ML training data
          const errMsg = error instanceof Error ? error.message : 'Unknown error';
          const errStatusCode = typeof err.statusCode === 'number' ? err.statusCode : undefined;
          trackExecution({
            eventType: 'agent_run',
            source: 'agent_chat',
            userId: authResult.userId ?? undefined,
            apiKeyId: authResult.apiKeyId ?? undefined,
            agentId: agent.id,
            status: 'error',
            durationMs: Date.now() - startTime,
            errorMessage: errMsg,
            errorCategory: inferErrorCategory({
              errorMessage: errMsg,
              statusCode: errStatusCode,
            }),
            // ML training data
            sequenceId,
            conversationId: conversation.id,
            availableToolCount: toolCount,
            contextMessageCount,
            contextTokenCount,
          });

          // Update conversation status to error
          prisma.conversation
            .update({
              where: { id: conversation.id },
              data: { status: 'error' },
            })
            .catch(() => {});

          // Track error
          if (authResult.userId) {
            trackUsage({
              apiKeyId: authResult.apiKeyId ?? undefined,
              userId: authResult.userId,
              endpoint: `/api/agents/${agentId}/conversation/${conversationId}`,
              method: 'POST',
              statusCode: 500,
              latencyMs: Date.now() - startTime,
              resourceType: 'agent',
              resourceId: agentId,
              errorCode: 'STREAM_ERROR',
              errorMessage: error instanceof Error ? error.message : 'Unknown error',
            });
          }
        } finally {
          controller.close();
        }
      },
    });

    return new NextResponse(stream, {
      headers: {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        Connection: 'keep-alive',
      },
    });
  } catch (error) {
    console.error('Failed to process message:', error);
    return NextResponse.json(
      {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to process message',
      },
      { status: 500 }
    );
  }
}

/**
 * GET /api/agents/[id]/conversation/[conversationId]
 * Retrieve conversation history with pagination
 *
 * Query params:
 * - limit: Max messages to return (default: 50, max: 100)
 * - before: Fetch messages created before this ISO timestamp (for loading older messages)
 * - after: Fetch messages created after this ISO timestamp (for loading newer messages)
 * - format: 'json' for full debug view (no pagination, includes agent info)
 *
 * Default behavior (no before/after): Returns the most recent messages
 * With before: Returns messages older than the timestamp (for scrolling up)
 * With after: Returns messages newer than the timestamp (for refreshing)
 */
export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
  const { id: agentId, conversationId } = await context.params;
  const { searchParams } = new URL(request.url);

  const format = searchParams.get('format');
  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
  const before = searchParams.get('before');
  const after = searchParams.get('after');

  try {
    // Fetch agent by ID with more details for JSON format
    const agent = await prisma.agent.findUnique({
      where: { id: agentId },
      select: {
        id: true,
        uid: true,
        name: true,
        provider: true,
        modelId: true,
        sandboxEnabled: true,
        executorType: true,
        executorConfig: true,
      },
    });

    if (!agent) {
      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
    }

    // Fetch conversation
    const conversation = await prisma.conversation.findUnique({
      where: {
        agentId_slug: {
          agentId: agent.id,
          slug: conversationId,
        },
      },
    });

    if (!conversation) {
      return NextResponse.json(
        { success: false, error: 'Conversation not found' },
        { status: 404 }
      );
    }

    // For JSON format, return all messages with full details
    if (format === 'json') {
      const allMessages = await prisma.message.findMany({
        where: { conversationId: conversation.id },
        orderBy: { createdAt: 'asc' },
      });

      const response = {
        _meta: {
          exportedAt: new Date().toISOString(),
          format: 'tpmjs-conversation-log',
          version: '1.0',
        },
        agent: {
          id: agent.id,
          uid: agent.uid,
          name: agent.name,
          provider: agent.provider,
          modelId: agent.modelId,
          executorType: agent.executorType,
          executorConfig: agent.executorConfig,
        },
        conversation: {
          id: conversation.id,
          slug: conversation.slug,
          title: conversation.title,
          status: conversation.status,
          createdAt: conversation.createdAt,
          updatedAt: conversation.updatedAt,
          messageCount: allMessages.length,
        },
        messages: allMessages.map((m) => ({
          id: m.id,
          role: m.role,
          content: m.content,
          toolCalls: m.toolCalls,
          toolCallId: m.toolCallId,
          toolName: m.toolName,
          toolResult: m.toolResult,
          inputTokens: m.inputTokens,
          outputTokens: m.outputTokens,
          // ML training fields
          availableToolCount: m.availableToolCount,
          availableToolNames: m.availableToolNames,
          sequenceId: m.sequenceId,
          contextMessageCount: m.contextMessageCount,
          contextTokenCount: m.contextTokenCount,
          createdAt: m.createdAt,
        })),
        stats: {
          totalMessages: allMessages.length,
          userMessages: allMessages.filter((m) => m.role === 'USER').length,
          assistantMessages: allMessages.filter((m) => m.role === 'ASSISTANT').length,
          toolResults: allMessages.filter((m) => m.role === 'TOOL').length,
          totalInputTokens: allMessages.reduce((sum, m) => sum + (m.inputTokens || 0), 0),
          totalOutputTokens: allMessages.reduce((sum, m) => sum + (m.outputTokens || 0), 0),
        },
      };

      // Return pretty-printed JSON with proper content type
      return new NextResponse(JSON.stringify(response, null, 2), {
        headers: {
          'Content-Type': 'application/json',
          'Content-Disposition': `inline; filename="${conversation.slug}-logs.json"`,
        },
      });
    }

    // Standard paginated response
    const whereClause: {
      conversationId: string;
      createdAt?: { lt?: Date; gt?: Date };
    } = { conversationId: conversation.id };

    if (before) {
      whereClause.createdAt = { lt: new Date(before) };
    } else if (after) {
      whereClause.createdAt = { gt: new Date(after) };
    }

    // Determine fetch order:
    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
    // - "after": Fetch asc (oldest first) to get messages after the cursor
    const shouldFetchDesc = !after;

    // Fetch messages
    const messages = await prisma.message.findMany({
      where: whereClause,
      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
      take: limit + 1,
    });

    const hasMore = messages.length > limit;
    let paginatedMessages = hasMore ? messages.slice(0, limit) : messages;

    // Reverse if we fetched in desc order to maintain chronological order
    if (shouldFetchDesc) {
      paginatedMessages = paginatedMessages.reverse();
    }

    const mappedMessages = paginatedMessages.map((m) => ({
      id: m.id,
      role: m.role,
      content: m.content,
      toolCalls: m.toolCalls,
      toolCallId: m.toolCallId,
      toolName: m.toolName,
      toolResult: m.toolResult,
      inputTokens: m.inputTokens,
      outputTokens: m.outputTokens,
      availableToolCount: m.availableToolCount,
      availableToolNames: m.availableToolNames,
      sequenceId: m.sequenceId,
      contextMessageCount: m.contextMessageCount,
      contextTokenCount: m.contextTokenCount,
      createdAt: m.createdAt,
    }));

    return NextResponse.json({
      success: true,
      data: {
        id: conversation.id,
        slug: conversation.slug,
        title: conversation.title,
        createdAt: conversation.createdAt,
        updatedAt: conversation.updatedAt,
        messages: mappedMessages,
      },
      pagination: {
        limit,
        hasMore,
        ...(before && { before }),
        ...(after && { after }),
      },
    });
  } catch (error) {
    console.error('Failed to fetch conversation:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to fetch conversation' },
      { status: 500 }
    );
  }
}

/**
 * DELETE /api/agents/[id]/conversation/[conversationId]
 * Delete a conversation
 */
export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
  const { id: agentId, conversationId } = await context.params;

  try {
    // Fetch agent by ID (include sandboxEnabled for cleanup)
    const agent = await prisma.agent.findUnique({
      where: { id: agentId },
      select: { id: true, sandboxEnabled: true },
    });

    if (!agent) {
      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
    }

    // Destroy sandbox session if applicable (fire-and-forget)
    if (agent.sandboxEnabled) {
      const { getSandboxConfig, destroySandboxSession } = await import('@/lib/executors');
      const { url: sandboxUrl, apiKey: sandboxApiKey } = getSandboxConfig();
      if (sandboxUrl) {
        const sessionId = `${agent.id}:${conversationId}`;
        destroySandboxSession(sandboxUrl, sandboxApiKey, sessionId).catch(() => {});
      }
    }

    // Delete conversation (messages cascade)
    await prisma.conversation.deleteMany({
      where: {
        agentId: agent.id,
        slug: conversationId,
      },
    });

    return NextResponse.json({
      success: true,
      data: { deleted: true },
    });
  } catch (error) {
    console.error('Failed to delete conversation:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to delete conversation' },
      { status: 500 }
    );
  }
}

/**
 * Agent Conversation Endpoint
 *
 * POST: Send a message and stream the AI response
 * GET: Retrieve conversation history
 * DELETE: Delete a conversation
 *
 * Route: /api/chat/[username]/[uid]/conversation/[conversationId]
 * Uses username/uid instead of agent id for cleaner public URLs
 */

import { randomUUID } from 'node:crypto';
import { Prisma, prisma } from '@tpmjs/db';
import type { AIProvider } from '@tpmjs/types/agent';
import { SendMessageSchema } from '@tpmjs/types/agent';
import type { LanguageModel, ModelMessage } from 'ai';
import { type NextRequest, NextResponse } from 'next/server';
import { decryptApiKey } from '@/lib/crypto/api-keys';
import { logActivity } from '~/lib/activity';
import { checkRateLimit, type RateLimitConfig } from '~/lib/rate-limit';

/**
 * Rate limit for chat messages: 30 requests per minute
 * This is stricter than default because chat involves expensive LLM calls
 */
const CHAT_RATE_LIMIT: RateLimitConfig = {
  limit: 30,
  windowSeconds: 60,
};

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 300; // 5 minutes for long agentic runs

type RouteContext = {
  params: Promise<{ username: string; uid: string; conversationId: string }>;
};

/**
 * Find agent by username and uid
 */
async function findAgentByUsernameAndUid(username: string, uid: string) {
  return prisma.agent.findFirst({
    where: {
      uid,
      user: { username },
    },
    select: { id: true, sandboxEnabled: true },
  });
}

/**
 * Get AI provider SDK based on provider type
 */
async function getProviderModel(
  provider: AIProvider,
  modelId: string,
  apiKey: string
): Promise<LanguageModel> {
  switch (provider) {
    case 'OPENAI': {
      const { createOpenAI } = await import('@ai-sdk/openai');
      return createOpenAI({ apiKey })(modelId);
    }
    case 'ANTHROPIC': {
      const { createAnthropic } = await import('@ai-sdk/anthropic');
      return createAnthropic({ apiKey })(modelId);
    }
    case 'GOOGLE': {
      const { createGoogleGenerativeAI } = await import('@ai-sdk/google');
      return createGoogleGenerativeAI({ apiKey })(modelId);
    }
    case 'GROQ': {
      const { createGroq } = await import('@ai-sdk/groq');
      return createGroq({ apiKey })(modelId);
    }
    case 'MISTRAL': {
      const { createMistral } = await import('@ai-sdk/mistral');
      return createMistral({ apiKey })(modelId);
    }
    default:
      throw new Error(`Unsupported provider: ${provider}`);
  }
}

/**
 * POST /api/chat/[username]/[uid]/conversation/[conversationId]
 * Send a message and stream the AI response via SSE
 */
// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: large streaming chat handler with auth, validation, and SSE logic
export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
  // Check rate limit first to prevent expensive LLM calls
  const rateLimitResponse = checkRateLimit(request, CHAT_RATE_LIMIT);
  if (rateLimitResponse) {
    return rateLimitResponse;
  }

  const { username, uid, conversationId } = await context.params;

  try {
    const body = await request.json();
    const parsed = SendMessageSchema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json(
        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
        { status: 400 }
      );
    }

    // Fetch agent with all tool relations using username + uid
    const { fetchAgentByUsernameAndUidWithTools, buildAgentTools } = await import(
      '@/lib/agents/build-tools'
    );
    const agent = await fetchAgentByUsernameAndUidWithTools(username, uid);

    if (!agent) {
      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
    }

    // Map provider to expected key name format
    const providerKeyNames: Record<string, string> = {
      OPENAI: 'OPENAI_API_KEY',
      ANTHROPIC: 'ANTHROPIC_API_KEY',
      GOOGLE: 'GOOGLE_API_KEY',
      GROQ: 'GROQ_API_KEY',
      MISTRAL: 'MISTRAL_API_KEY',
    };
    const keyName = providerKeyNames[agent.provider];

    if (!keyName) {
      return NextResponse.json(
        { success: false, error: `Unsupported provider: ${agent.provider}` },
        { status: 400 }
      );
    }

    // Get user's API key for this provider
    const userApiKey = await prisma.userApiKey.findUnique({
      where: {
        userId_keyName: {
          userId: agent.userId,
          keyName,
        },
      },
    });

    if (!userApiKey) {
      return NextResponse.json(
        {
          success: false,
          error: `No API key configured for ${agent.provider}. Please add your API key in settings.`,
        },
        { status: 400 }
      );
    }

    // Decrypt the API key
    const apiKey = decryptApiKey(userApiKey.encryptedKey, userApiKey.keyIv);

    // Get or create conversation
    let conversation = await prisma.conversation.findUnique({
      where: {
        agentId_slug: {
          agentId: agent.id,
          slug: conversationId,
        },
      },
    });

    if (!conversation) {
      conversation = await prisma.conversation.create({
        data: {
          agentId: agent.id,
          slug: conversationId,
          title: parsed.data.message.slice(0, 100),
        },
      });

      // Log activity for new conversation (fire-and-forget)
      if (agent.userId) {
        logActivity({
          userId: agent.userId,
          type: 'AGENT_CONVERSATION_STARTED',
          targetName: agent.name,
          targetType: 'agent',
          agentId: agent.id,
        });
      }
    }

    // Fetch recent messages for context
    const recentMessages = await prisma.message.findMany({
      where: { conversationId: conversation.id },
      orderBy: { createdAt: 'desc' },
      take: agent.maxMessagesInContext,
    });

    // Reverse to get chronological order
    recentMessages.reverse();

    // Save user message
    await prisma.message.create({
      data: {
        conversationId: conversation.id,
        role: 'USER',
        content: parsed.data.message,
      },
    });

    // Build AI SDK messages from conversation history
    const { streamText, stepCountIs } = await import('ai');

    const messages: ModelMessage[] = [];

    // Add system prompt if defined
    if (agent.systemPrompt) {
      messages.push({
        role: 'system',
        content: agent.systemPrompt,
      });
    }

    // Build a set of tool call IDs that have corresponding tool results
    // This is needed because AI SDK requires every tool call to have a matching tool result
    const toolResultIds = new Set(
      recentMessages.filter((m) => m.role === 'TOOL' && m.toolCallId).map((m) => m.toolCallId)
    );

    // Add conversation history - properly format for AI SDK
    for (const msg of recentMessages) {
      if (msg.role === 'USER') {
        messages.push({ role: 'user', content: msg.content });
      } else if (msg.role === 'ASSISTANT') {
        // For assistant messages with tool calls, include ToolCallParts in content
        if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
          // Only include tool calls that have matching tool results
          // AI SDK fails if there's a tool call without a corresponding tool result
          const validToolCalls = (
            msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
          ).filter((tc) => toolResultIds.has(tc.toolCallId));

          if (validToolCalls.length > 0) {
            const toolCallParts = validToolCalls.map((tc) => ({
              type: 'tool-call' as const,
              toolCallId: tc.toolCallId,
              toolName: tc.toolName,
              input: tc.args,
            }));
            // Content includes text (if any) plus tool call parts
            const content: Array<
              | { type: 'text'; text: string }
              | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
            > = [];
            if (msg.content) {
              content.push({ type: 'text', text: msg.content });
            }
            content.push(...toolCallParts);
            messages.push({
              role: 'assistant',
              content,
            });
          } else {
            // All tool calls are missing results, just include text content
            messages.push({
              role: 'assistant',
              content: msg.content || '',
            });
          }
        } else {
          messages.push({
            role: 'assistant',
            content: msg.content,
          });
        }
      } else if (msg.role === 'TOOL') {
        // Tool results use the 'tool' role with content array
        messages.push({
          role: 'tool',
          content: [
            {
              type: 'tool-result' as const,
              toolCallId: msg.toolCallId || '',
              toolName: msg.toolName || '',
              output: {
                type: 'json' as const,
                value: msg.toolResult,
              },
            },
          ],
        });
      }
    }

    // Add new user message
    messages.push({ role: 'user', content: parsed.data.message });

    // Set up sandbox session if agent has sandbox enabled
    let sessionId: string | undefined;
    let _sandboxUrl: string | undefined;
    let _sandboxApiKey: string | undefined;
    if (agent.sandboxEnabled) {
      const { getSandboxConfig, createSandboxSession } = await import('@/lib/executors');
      const { url: sandboxUrl, apiKey: sandboxApiKey } = getSandboxConfig();
      if (!sandboxUrl) {
        return NextResponse.json(
          {
            success: false,
            error: 'Sandbox not available. AGENT_SANDBOX_URL is not configured.',
          },
          { status: 502 }
        );
      }
      _sandboxUrl = sandboxUrl;
      _sandboxApiKey = sandboxApiKey;
      sessionId = `${agent.id}:${conversationId}`;
      try {
        await createSandboxSession(sandboxUrl, sandboxApiKey, sessionId);
      } catch (error) {
        console.error('[Sandbox] Failed to create session:', error);
        return NextResponse.json(
          {
            success: false,
            error: `Failed to create sandbox session: ${error instanceof Error ? error.message : 'Unknown error'}`,
          },
          { status: 502 }
        );
      }
    }

    // Set up approval handler for tools with "ask" permission
    const { parseToolPermissions } = await import('@/lib/agents/permissions');
    const permissions = parseToolPermissions(agent.toolPermissions);
    const hasPendingApprovals = permissions !== null;
    let approvalSendEvent: ((event: string, data: unknown) => void) | null = null;

    // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: DB-polling approval flow with timeout logic
    async function handleToolApproval(toolName: string, input: unknown): Promise<boolean> {
      const toolCallId = randomUUID();
      const approval = await prisma.toolApproval.create({
        data: {
          conversationId: conversation.id,
          agentId: agent.id,
          toolCallId,
          toolName,
          inputArgs: input as object,
        },
      });
      if (approvalSendEvent) {
        approvalSendEvent('approval_request', { approvalId: approval.id, toolName, input });
      }
      const POLL_INTERVAL = 2000;
      const TIMEOUT = 120000;
      const start = Date.now();
      while (Date.now() - start < TIMEOUT) {
        await new Promise((r) => setTimeout(r, POLL_INTERVAL));
        const updated = await prisma.toolApproval.findUnique({
          where: { id: approval.id },
          select: { decision: true },
        });
        if (updated?.decision) {
          if (approvalSendEvent) {
            approvalSendEvent('approval_resolved', {
              approvalId: approval.id,
              decision: updated.decision,
            });
          }
          return updated.decision === 'approve';
        }
      }
      await prisma.toolApproval.update({
        where: { id: approval.id },
        data: { decision: 'deny', resolvedAt: new Date() },
      });
      if (approvalSendEvent) {
        approvalSendEvent('approval_timeout', { approvalId: approval.id, toolName });
      }
      return false;
    }
    const approvalHandler = hasPendingApprovals ? handleToolApproval : undefined;

    // Build tools from agent configuration
    const tools = buildAgentTools(
      agent,
      undefined,
      sessionId,
      _sandboxUrl,
      _sandboxApiKey,
      approvalHandler
    );

    // Get the provider model
    const model = await getProviderModel(agent.provider, agent.modelId, apiKey);

    // Create SSE stream
    const stream = new ReadableStream({
      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: SSE streaming with tool calls and error handling
      async start(controller) {
        const encoder = new TextEncoder();

        const sendEvent = (event: string, data: unknown) => {
          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
          controller.enqueue(encoder.encode(message));
        };

        // Bind approval SSE sender
        approvalSendEvent = sendEvent;

        try {
          const startTime = Date.now();
          let fullContent = '';
          // Accumulate tool calls with their input args
          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
            new Map();
          // Collect tool results to save AFTER assistant message (for correct chronological order)
          const pendingToolResults: Array<{
            toolCallId: string;
            toolName: string;
            output: unknown;
          }> = [];
          let inputTokens = 0;
          let outputTokens = 0;

          // Stream the response with agentic loop control
          const result = await streamText({
            model,
            messages,
            tools,
            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
            onChunk: async ({ chunk }) => {
              // Stream tool calls as they come in and capture their inputs
              if (chunk.type === 'tool-call') {
                const input = 'args' in chunk ? chunk.args : chunk.input;
                // Store tool call with input for later persistence
                toolCallsMap.set(chunk.toolCallId, {
                  toolCallId: chunk.toolCallId,
                  toolName: chunk.toolName,
                  args: input,
                });
                sendEvent('tool_call', {
                  toolCallId: chunk.toolCallId,
                  toolName: chunk.toolName,
                  input,
                });
              }
            },
            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: step finish handler with tool call tracking and usage aggregation
            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
              // Capture tool calls from step finish (backup in case onChunk missed any)
              if (toolCalls && Array.isArray(toolCalls)) {
                for (const tc of toolCalls) {
                  if (!toolCallsMap.has(tc.toolCallId)) {
                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
                    const args =
                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
                    toolCallsMap.set(tc.toolCallId, {
                      toolCallId: tc.toolCallId,
                      toolName: tc.toolName,
                      args,
                    });
                  }
                }
              }

              // Send tool results via SSE but don't save yet (save after assistant message for correct order)
              if (toolResults && toolResults.length > 0) {
                for (const tr of toolResults) {
                  sendEvent('tool_result', {
                    toolCallId: tr.toolCallId,
                    output: tr.output,
                  });

                  // Collect tool results to save after assistant message
                  pendingToolResults.push({
                    toolCallId: tr.toolCallId,
                    toolName: tr.toolName,
                    output: tr.output,
                  });
                }
              }

              // Track token usage
              if (usage) {
                inputTokens += usage.inputTokens ?? 0;
                outputTokens += usage.outputTokens ?? 0;
              }
            },
          });

          // Stream text chunks
          for await (const chunk of result.textStream) {
            fullContent += chunk;
            sendEvent('chunk', { type: 'text', text: chunk });
          }

          // Get final response data
          const finalUsage = await result.usage;

          // Convert tool calls map to array for storage
          const allToolCalls = Array.from(toolCallsMap.values());

          // Update token counts from final usage
          if (finalUsage) {
            inputTokens = finalUsage.inputTokens ?? inputTokens;
            outputTokens = finalUsage.outputTokens ?? outputTokens;
          }

          // Save assistant message FIRST (so it has earlier createdAt than tool results)
          const assistantMessage = await prisma.message.create({
            data: {
              conversationId: conversation.id,
              role: 'ASSISTANT',
              content: fullContent,
              // Cast to Prisma-compatible JSON type
              toolCalls:
                allToolCalls.length > 0
                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
                  : Prisma.JsonNull,
              inputTokens,
              outputTokens,
            },
          });

          // Now save TOOL messages (after assistant, for correct chronological order)
          for (const tr of pendingToolResults) {
            await prisma.message.create({
              data: {
                conversationId: conversation.id,
                role: 'TOOL',
                content: JSON.stringify(tr.output),
                toolCallId: tr.toolCallId,
                toolName: tr.toolName,
                toolResult: tr.output as object,
              },
            });
          }

          // Update conversation timestamp
          await prisma.conversation.update({
            where: { id: conversation.id },
            data: { updatedAt: new Date() },
          });

          const executionTimeMs = Date.now() - startTime;

          // Send token usage
          sendEvent('tokens', {
            inputTokens,
            outputTokens,
            totalTokens: inputTokens + outputTokens,
          });

          // Send completion event
          sendEvent('complete', {
            messageId: assistantMessage.id,
            conversationId: conversation.id,
            executionTimeMs,
          });
        } catch (error) {
          console.error('Agent conversation error:', error);
          sendEvent('error', {
            message: error instanceof Error ? error.message : 'Unknown error',
          });
        } finally {
          controller.close();
        }
      },
    });

    return new NextResponse(stream, {
      headers: {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        Connection: 'keep-alive',
      },
    });
  } catch (error) {
    console.error('Failed to process message:', error);
    return NextResponse.json(
      {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to process message',
      },
      { status: 500 }
    );
  }
}

/**
 * GET /api/chat/[username]/[uid]/conversation/[conversationId]
 * Retrieve conversation history with pagination
 *
 * Query params:
 * - limit: Max messages to return (default: 50, max: 100)
 * - before: Fetch messages created before this ISO timestamp (for loading older messages)
 * - after: Fetch messages created after this ISO timestamp (for loading newer messages)
 *
 * Default behavior (no before/after): Returns the most recent messages
 * With before: Returns messages older than the timestamp (for scrolling up)
 * With after: Returns messages newer than the timestamp (for refreshing)
 */
export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
  const { username, uid, conversationId } = await context.params;
  const { searchParams } = new URL(request.url);

  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
  const before = searchParams.get('before');
  const after = searchParams.get('after');

  try {
    // Fetch agent by username and uid
    const agent = await findAgentByUsernameAndUid(username, uid);

    if (!agent) {
      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
    }

    // Fetch conversation
    const conversation = await prisma.conversation.findUnique({
      where: {
        agentId_slug: {
          agentId: agent.id,
          slug: conversationId,
        },
      },
    });

    if (!conversation) {
      return NextResponse.json(
        { success: false, error: 'Conversation not found' },
        { status: 404 }
      );
    }

    // Build the where clause based on cursor
    const whereClause: {
      conversationId: string;
      createdAt?: { lt?: Date; gt?: Date };
    } = { conversationId: conversation.id };

    if (before) {
      whereClause.createdAt = { lt: new Date(before) };
    } else if (after) {
      whereClause.createdAt = { gt: new Date(after) };
    }

    // Determine fetch order:
    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
    // - "after": Fetch asc (oldest first) to get messages after the cursor
    const shouldFetchDesc = !after;

    // Fetch messages
    const messages = await prisma.message.findMany({
      where: whereClause,
      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
      take: limit + 1,
    });

    const hasMore = messages.length > limit;
    let paginatedMessages = hasMore ? messages.slice(0, limit) : messages;

    // Reverse if we fetched in desc order to maintain chronological order
    if (shouldFetchDesc) {
      paginatedMessages = paginatedMessages.reverse();
    }

    const mappedMessages = paginatedMessages.map((m) => ({
      id: m.id,
      role: m.role,
      content: m.content,
      toolCalls: m.toolCalls,
      toolCallId: m.toolCallId,
      toolName: m.toolName,
      toolResult: m.toolResult,
      inputTokens: m.inputTokens,
      outputTokens: m.outputTokens,
      createdAt: m.createdAt,
    }));

    return NextResponse.json({
      success: true,
      data: {
        id: conversation.id,
        slug: conversation.slug,
        title: conversation.title,
        createdAt: conversation.createdAt,
        updatedAt: conversation.updatedAt,
        messages: mappedMessages,
      },
      pagination: {
        limit,
        hasMore,
        ...(before && { before }),
        ...(after && { after }),
      },
    });
  } catch (error) {
    console.error('Failed to fetch conversation:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to fetch conversation' },
      { status: 500 }
    );
  }
}

/**
 * DELETE /api/chat/[username]/[uid]/conversation/[conversationId]
 * Delete a conversation
 */
export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
  const { username, uid, conversationId } = await context.params;

  try {
    // Fetch agent by username and uid
    const agent = await findAgentByUsernameAndUid(username, uid);

    if (!agent) {
      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
    }

    // Destroy sandbox session if applicable (fire-and-forget)
    if (agent.sandboxEnabled) {
      const { getSandboxConfig, destroySandboxSession } = await import('@/lib/executors');
      const { url: sandboxUrl, apiKey: sandboxApiKey } = getSandboxConfig();
      if (sandboxUrl) {
        const sessionId = `${agent.id}:${conversationId}`;
        destroySandboxSession(sandboxUrl, sandboxApiKey, sessionId).catch(() => {});
      }
    }

    // Delete conversation (messages cascade)
    await prisma.conversation.deleteMany({
      where: {
        agentId: agent.id,
        slug: conversationId,
      },
    });

    return NextResponse.json({
      success: true,
      data: { deleted: true },
    });
  } catch (error) {
    console.error('Failed to delete conversation:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to delete conversation' },
      { status: 500 }
    );
  }
}

